window.CONTENT = [{"id": "air-01", "title": "シカゴ行き便の搭乗案内", "cat": "air", "type": "空港・機内アナウンス", "level": "TOEIC 600", "voice": "m", "s": [["Attention, passengers traveling to Chicago on Midway Air flight 218.", "ミッドウェイ航空218便でシカゴへお越しのお客様にご案内いたします。"], ["We are now ready to begin boarding at Gate 14.", "ただいまより、14番ゲートで搭乗を開始いたします。"], ["Passengers with small children may board first.", "小さなお子様連れのお客様は、先にご搭乗いただけます。"], ["Please have your boarding pass and passport ready for the agent.", "係員にお見せできるよう、搭乗券とパスポートをご用意ください。"], ["Everyone else will be called by row number, starting with the back of the plane.", "その他のお客様は、機体の後方から順に座席の列番号でお呼びいたします。"], ["The flight will leave at 9:30 A.M., and the door closes ten minutes before that.", "便は午前9:30に出発し、その10分前にドアが閉まります。"], ["Thank you for flying with us today.", "本日はご搭乗いただき、誠にありがとうございます。"]]}, {"id": "air-02", "title": "出発ゲート変更のお知らせ", "cat": "air", "type": "空港・機内アナウンス", "level": "TOEIC 730", "voice": "f", "s": [["May I have your attention, please, passengers booked on Harbor Airlines flight 507 to Denver?", "ハーバー航空507便デンバー行きをご予約のお客様に、ご案内申し上げます。"], ["The departure gate has been changed from Gate 22 to Gate 9.", "出発ゲートが22番ゲートから9番ゲートに変更になりました。"], ["Gate 9 is in the same terminal, about a five-minute walk past the food court.", "9番ゲートは同じターミナル内にあり、フードコートを過ぎて徒歩約5分です。"], ["We apologize for the inconvenience this change may cause.", "この変更によりご不便をおかけしますことをお詫び申し上げます。"], ["Boarding is still scheduled to begin at 2:15 P.M., so you have plenty of time.", "搭乗は予定どおり午後2:15に開始いたしますので、時間には十分余裕がございます。"], ["If you need help getting to the new gate, please ask any staff member in a blue vest.", "新しいゲートまでの道順でお困りの場合は、青いベストを着たスタッフにお尋ねください。"], ["Updated information is also shown on the monitors throughout the terminal.", "最新の情報は、ターミナル内の各モニターにも表示されています。"]]}, {"id": "air-03", "title": "悪天候による遅延案内", "cat": "air", "type": "空港・機内アナウンス", "level": "TOEIC 860", "voice": "m", "s": [["This is an important update for passengers on Summit Air flight 3309 to Portland.", "皆様にご案内いたします。サミット航空3309便ポートランド行きをご利用のお客様への重要なお知らせです。"], ["Because of heavy snow at our destination, the flight has been delayed by approximately two hours.", "目的地での大雪のため、この便は約2時間遅れております。"], ["Our operations team is monitoring the weather closely, and we will announce a new departure time as soon as conditions improve.", "運航部門は天候を注意深く監視しており、状況が改善次第、新しい出発時刻をお知らせいたします。"], ["Passengers who prefer to rebook on a later flight may do so at the service counter near Gate 6 free of charge.", "後の便への振替をご希望のお客様は、6番ゲート近くのサービスカウンターで無料で手続きいただけます。"], ["Meal vouchers will be given to every passenger with a confirmed reservation who remains in the boarding area.", "予約が確定していて搭乗エリアにお残りのすべてのお客様に、お食事券をお配りいたします。"], ["We sincerely apologize for the disruption to your travel plans.", "お客様のご旅行の予定に支障が出ておりますことを、心よりお詫び申し上げます。"], ["Thank you for your patience and understanding.", "ご辛抱とご理解をいただき、ありがとうございます。"]]}, {"id": "air-04", "title": "手荷物受取所のご案内", "cat": "air", "type": "空港・機内アナウンス", "level": "TOEIC 600", "voice": "f", "s": [["Welcome to Lakeview International Airport, where the local time is 4:40 P.M.", "レイクビュー国際空港へようこそ。現地時間は午後4:40です。"], ["Passengers from flight 88 from Seattle, please go to baggage claim carousel number 3.", "シアトルからの88便をご利用のお客様は、3番の手荷物受取ターンテーブルへお進みください。"], ["Your bags should arrive in about ten minutes.", "お荷物は約10分でお手元に届く予定です。"], ["Please check the name tag on your bag before you leave the carousel.", "ターンテーブルを離れる前に、お荷物の名札をご確認ください。"], ["Free luggage carts are available near the exit doors.", "出口付近に、無料の荷物カートをご用意しております。"], ["If your bag is missing or damaged, please visit the service desk next to carousel 1.", "お荷物が見つからない場合や破損している場合は、1番ターンテーブル横のサービスデスクにお越しください。"], ["Thank you, and enjoy your stay.", "ありがとうございました。ご滞在をお楽しみください。"]]}, {"id": "air-05", "title": "機内での安全に関する案内", "cat": "air", "type": "空港・機内アナウンス", "level": "TOEIC 730", "voice": "m", "s": [["Welcome aboard Blue Coast Airways flight 64 to San Diego.", "ブルーコースト航空64便サンディエゴ行きへようこそ。"], ["Please take a moment to listen to this important safety information.", "しばらくの間、この大切な安全に関するご案内をお聞きください。"], ["Make sure your seat belt is fastened low and tight across your lap whenever the sign is on.", "サインが点灯しているときは、シートベルトを腰の低い位置にしっかりと締めてください。"], ["In the unlikely event of a loss of cabin pressure, oxygen masks will drop from above your seat.", "万が一、機内の気圧が低下した場合には、座席の上から酸素マスクが落ちてきます。"], ["Pull the mask toward you, place it over your nose and mouth, and breathe normally.", "マスクを手前に引き、鼻と口を覆って、普通に呼吸してください。"], ["Your life vest is located under your seat, and exits are marked with lighted signs.", "救命胴衣は座席の下にあり、非常口は点灯する標識で示されています。"], ["Please also turn off or switch your phones to airplane mode before takeoff.", "また、離陸前に携帯電話の電源をお切りになるか、機内モードに切り替えてください。"]]}, {"id": "air-06", "title": "機内サービスと到着予定", "cat": "air", "type": "空港・機内アナウンス", "level": "TOEIC 860", "voice": "f", "s": [["Good afternoon, this is your purser speaking on behalf of the entire cabin crew.", "こんにちは。客室乗務員一同を代表して、チーフパーサーがご案内いたします。"], ["We will begin our complimentary beverage service shortly, followed by a choice of two hot meals.", "まもなく無料の飲み物サービスを開始し、続いて2種類の温かいお食事からお選びいただけます。"], ["Passengers with special dietary requirements who ordered in advance will be served first.", "事前にご注文いただいた特別食のお客様には、先にお配りいたします。"], ["Wireless internet is available for purchase, and connection instructions appear on the screen in front of you.", "無線インターネットは有料でご利用いただけます。接続方法は目の前の画面に表示されています。"], ["We expect to land in Boston approximately twenty minutes ahead of schedule, thanks to favorable tailwinds.", "追い風のおかげで、ボストンには予定より約20分早く到着する見込みです。"], ["Before we land, our crew will collect any trash and ask you to return your seat to the upright position.", "着陸前に、乗務員がごみを回収し、座席を元の位置に戻していただくようお願いいたします。"], ["We hope to welcome you aboard again soon.", "またのご搭乗をお待ちしております。"]]}, {"id": "air-07", "title": "入国時の税関申告の案内", "cat": "air", "type": "空港・機内アナウンス", "level": "TOEIC 730", "voice": "m", "s": [["Welcome to the United States, and thank you for your cooperation at customs.", "アメリカ合衆国へようこそ。税関でのご協力に感謝いたします。"], ["All travelers must complete a customs declaration form before reaching the inspection area.", "すべての旅行者は、検査エリアに着く前に税関申告書をご記入ください。"], ["Please declare any fresh food, plants, or cash totaling more than 10,000 dollars.", "生鮮食品、植物、または合計1万ドルを超える現金は、必ず申告してください。"], ["Families traveling together may submit one form for the entire group.", "ご家族でご一緒に旅行される場合は、グループ全体で1枚の申告書を提出できます。"], ["Passengers with nothing to declare should follow the green signs to the right.", "申告するものがないお客様は、右側の緑色の標識に従ってお進みください。"], ["Officers may ask to inspect your luggage, so please keep your bags with you at all times.", "係官が荷物の検査を求める場合がありますので、お荷物は常にお手元に置いてください。"], ["We appreciate your patience during busy hours.", "混雑する時間帯にご辛抱いただき、ありがとうございます。"]]}, {"id": "air-08", "title": "空港での忘れ物のお知らせ", "cat": "air", "type": "空港・機内アナウンス", "level": "TOEIC 600", "voice": "f", "s": [["This is an announcement from the Lost and Found office at Terminal 2.", "こちらは第2ターミナルの遺失物取扱所からのお知らせです。"], ["A black leather bag was left near Gate 18 about thirty minutes ago.", "約30分前に、18番ゲート付近で黒い革のかばんが見つかりました。"], ["The bag has a red tag with the name Mr. Peter Collins.", "かばんには、ピーター・コリンズさんの名前が書かれた赤い札が付いています。"], ["If you are Mr. Collins, please come to the information desk on the first floor.", "コリンズさんご本人は、1階の案内デスクまでお越しください。"], ["You will need to show your passport to pick up the bag.", "かばんをお受け取りの際は、パスポートをご提示いただく必要があります。"], ["Other lost items can be claimed at our office from 8:00 A.M. to 8:00 P.M.", "その他の忘れ物は、当事務所で午前8:00から午後8:00までお受け取りいただけます。"], ["Thank you very much for your help.", "ご協力をいただき、誠にありがとうございます。"]]}, {"id": "air-09", "title": "空港ラウンジの利用案内", "cat": "air", "type": "空港・機内アナウンス", "level": "TOEIC 730", "voice": "m", "s": [["Welcome to the Skyline Lounge, open to business class and gold members.", "ビジネスクラスとゴールド会員のお客様がご利用いただける、スカイラインラウンジへようこそ。"], ["The lounge is located on the third floor, just past the security checkpoint.", "ラウンジは3階の、保安検査場を過ぎてすぐの場所にあります。"], ["Guests may enjoy free snacks, hot drinks, and high-speed internet throughout their stay.", "ご滞在中は、無料の軽食、温かい飲み物、高速インターネットをお楽しみいただけます。"], ["Shower rooms are available on a first-come, first-served basis at the front desk.", "シャワールームは、フロントで先着順にご利用いただけます。"], ["Please note that the lounge will close at 11:00 P.M. tonight for cleaning.", "ラウンジは、清掃のため本日午後11:00に閉まりますのでご注意ください。"], ["Our staff will remind you when your flight begins boarding, so please relax and enjoy your visit.", "ご搭乗のご案内が始まりましたらスタッフがお知らせしますので、どうぞごゆっくりお過ごしください。"], ["We hope you have a pleasant journey.", "どうぞ快適な旅をお楽しみください。"]]}, {"id": "air-10", "title": "欠航と振替手続きのお詫び", "cat": "air", "type": "空港・機内アナウンス", "level": "TOEIC 860", "voice": "f", "s": [["Attention, passengers on Northern Pacific flight 912 to Minneapolis.", "ノーザンパシフィック航空912便ミネアポリス行きをご利用のお客様にお知らせいたします。"], ["We regret to announce that this flight has been canceled because of a mechanical problem.", "誠に残念ながら、この便は機械的なトラブルのため欠航となりました。"], ["Our maintenance crew needs additional time to complete a safety inspection that cannot be finished tonight.", "整備チームには安全点検を完了するための追加の時間が必要で、点検は今夜中には終わりません。"], ["All affected passengers have been rebooked on tomorrow's 7:45 A.M. departure, and new boarding passes will be emailed to you.", "影響を受けるすべてのお客様は、明日の午前7:45発の便に振り替えられており、新しい搭乗券はメールでお送りします。"], ["Hotel accommodations and transportation are being arranged for anyone who lives outside the metropolitan area.", "都市圏の外にお住まいのお客様には、ホテルの宿泊と交通手段を手配しております。"], ["Please see the representatives at Gate 11 to collect your vouchers, or request a full refund if you would prefer.", "11番ゲートの係員のところで宿泊券をお受け取りください。ご希望の場合は全額払い戻しもお申し込みいただけます。"], ["We deeply apologize for the inconvenience.", "ご迷惑をおかけしますことを深くお詫び申し上げます。"]]}, {"id": "store-01", "title": "スーパーの閉店前の案内", "cat": "store", "type": "店内・施設アナウンス", "level": "TOEIC 600", "voice": "m", "s": [["Attention, all shoppers at Greenfield Market this evening.", "グリーンフィールドマーケットをご利用のお客様にご案内いたします。"], ["Our store will close in thirty minutes, at 9:00 P.M.", "当店は30分後の午後9:00に閉店いたします。"], ["Please bring your final items to the checkout counters at the front of the store.", "最後のお買い物の品を、店の前方にあるレジまでお持ちください。"], ["Self-checkout machines will stop working at 8:50 P.M.", "セルフレジは午後8:50で利用を終了いたします。"], ["Fresh bread and salads are now half price at the bakery counter.", "ベーカリーカウンターでは、焼きたてのパンとサラダが半額になっております。"], ["We will open again tomorrow morning at 7:00 A.M., and we look forward to seeing you.", "明日は朝の午前7:00に再開いたします。またのご来店をお待ちしております。"], ["Thank you for shopping with us today.", "本日はご来店いただき、ありがとうございました。"]]}, {"id": "store-02", "title": "デパートの週末特売案内", "cat": "store", "type": "店内・施設アナウンス", "level": "TOEIC 730", "voice": "f", "s": [["Good afternoon, shoppers, and welcome to Mason's Department Store.", "こんにちは、お客様。メイソンズ百貨店へようこそ。"], ["This weekend only, all winter coats on the second floor are 30 percent off.", "今週末限定で、2階のすべての冬物コートが30パーセント引きです。"], ["Customers who spend more than 100 dollars on the second floor will receive a free scarf.", "2階で100ドルを超えてお買い上げのお客様には、スカーフを無料で差し上げます。"], ["The sale starts today at 1:00 P.M. and ends on Sunday at closing time.", "セールは本日の午後1:00に始まり、日曜日の閉店時間まで行います。"], ["Please note that sale items cannot be returned for cash, but they may be exchanged within fourteen days.", "セール品は返金できませんが、14日以内であれば交換いただけますのでご注意ください。"], ["Our personal shoppers are available near the escalator to help you find the perfect size.", "エスカレーターの近くに専属スタッフがおり、ぴったりのサイズ選びをお手伝いいたします。"], ["Thank you, and enjoy your visit.", "ありがとうございます。どうぞお買い物をお楽しみください。"]]}, {"id": "store-03", "title": "ショッピングセンターの迷子案内", "cat": "store", "type": "店内・施設アナウンス", "level": "TOEIC 860", "voice": "m", "s": [["May I have your attention, please, all customers at Riverside Shopping Center?", "リバーサイドショッピングセンターにお越しのお客様にご案内申し上げます。"], ["We are looking for the parents or guardians of a young boy named Tommy.", "トミー君という小さな男の子の、保護者の方をお探ししております。"], ["He is about five years old, has short brown hair, and is wearing a green jacket with blue shoes.", "年齢は5歳くらいで、短い茶色の髪をして、緑色の上着と青い靴を身につけています。"], ["Tommy is currently waiting safely at the customer service desk, which is located beside the main entrance.", "トミー君は現在、正面入口の横にあるお客様サービスデスクで、安全にお待ちです。"], ["If you are his parent, please come to the desk immediately and bring a form of photo identification.", "保護者の方は、すぐにデスクまでお越しいただき、写真付きの身分証明書をお持ちください。"], ["Shoppers who see a child walking alone are kindly asked to notify the nearest staff member.", "お子様が一人で歩いているのをお見かけの際は、最寄りのスタッフまでお知らせください。"], ["We thank you for your cooperation.", "ご協力に感謝申し上げます。"]]}, {"id": "store-04", "title": "図書館の閉館前アナウンス", "cat": "store", "type": "店内・施設アナウンス", "level": "TOEIC 600", "voice": "f", "s": [["Attention, visitors to the Maple Street Public Library.", "メープルストリート公立図書館にお越しの皆様にご案内いたします。"], ["The library will close in fifteen minutes, at 6:00 P.M.", "図書館は15分後の午後6:00に閉館いたします。"], ["Please bring any books you want to borrow to the front desk.", "借りたい本は、受付カウンターまでお持ちください。"], ["Books that are due today can be returned in the box outside the door.", "本日が返却期限の本は、入口の外にある返却ボックスにお返しいただけます。"], ["Computers will shut down in five minutes, so please save your work.", "コンピューターは5分後に停止しますので、作業内容を保存してください。"], ["The library will open again tomorrow at 9:00 A.M.", "図書館は明日の午前9:00に再開いたします。"], ["Thank you for visiting, and have a nice evening.", "ご利用ありがとうございました。どうぞ素敵な夜をお過ごしください。"]]}, {"id": "store-05", "title": "美術館の特別展のご案内", "cat": "store", "type": "店内・施設アナウンス", "level": "TOEIC 730", "voice": "m", "s": [["Welcome to the Oakdale Art Museum, home of the new Modern Light exhibition.", "新しいモダンライト展を開催中の、オークデール美術館へようこそ。"], ["The special exhibit is on the third floor and is open until 5:30 P.M. today.", "特別展は3階で、本日は午後5:30まで開いております。"], ["Photography is allowed in most galleries, but flash and tripods are not permitted.", "ほとんどの展示室で撮影は可能ですが、フラッシュと三脚はご使用いただけません。"], ["Please do not touch the artwork, and keep a safe distance from all paintings.", "作品には触れず、すべての絵画から安全な距離を保ってください。"], ["Free guided tours depart from the main lobby every hour on the hour.", "無料のガイドツアーは、毎正時にメインロビーから出発します。"], ["Audio guides can be rented at the information desk for five dollars.", "音声ガイドは、案内デスクで5ドルでお借りいただけます。"], ["The museum shop and cafe are on the first floor, near the exit.", "ミュージアムショップとカフェは、1階の出口の近くにあります。"]]}, {"id": "store-06", "title": "ジムの利用規則変更案内", "cat": "store", "type": "店内・施設アナウンス", "level": "TOEIC 860", "voice": "f", "s": [["Good evening, members, and thank you for your attention.", "こんばんは、会員の皆様。お聞きいただきありがとうございます。"], ["We would like to inform you of several changes to our facility policies that take effect on Monday.", "月曜日から施行される、当施設の規則のいくつかの変更についてお知らせいたします。"], ["Beginning next week, the swimming pool will close at 9:00 P.M., one hour earlier than usual, for routine maintenance.", "来週から、定期的なメンテナンスのため、プールは通常より1時間早い午後9:00に閉まります。"], ["Members who wish to reserve a personal training session must now do so at least twenty-four hours in advance.", "パーソナルトレーニングの予約をご希望の会員様は、今後は24時間以上前までにお申し込みいただく必要があります。"], ["Any locker still locked after closing will be emptied, and its contents kept at the front desk for thirty days.", "閉館後も施錠されたままのロッカーは中身を取り出し、受付で30日間保管いたします。"], ["We apologize for any inconvenience, and we appreciate your understanding as we improve our services.", "ご不便をおかけしましたらお詫び申し上げます。サービス向上のため、ご理解をお願いいたします。"]]}, {"id": "store-07", "title": "駐車場の階の閉鎖のお知らせ", "cat": "store", "type": "店内・施設アナウンス", "level": "TOEIC 730", "voice": "m", "s": [["Attention, drivers parked in the Central Plaza parking garage.", "セントラルプラザの立体駐車場にお車を停めているお客様にご案内いたします。"], ["Due to a water leak on Level 2, that floor will be closed until further notice.", "2階で水漏れが発生したため、そのフロアは追って通知があるまで閉鎖されます。"], ["Please move your vehicle to Level 3 or Level 4 as soon as possible.", "できるだけ早く、お車を3階か4階に移動してください。"], ["Parking fees will be waived for customers who must change levels.", "階を移動していただくお客様の駐車料金は、免除いたします。"], ["Staff members in yellow jackets will guide you to available spaces.", "黄色い上着を着たスタッフが、空いているスペースへご案内します。"], ["Remember to take your parking ticket with you and pay at the machine before you return to your car.", "駐車券をお持ちになり、お車に戻る前に精算機でお支払いください。"], ["We are sorry for the trouble, and thank you for your patience.", "ご迷惑をおかけして申し訳ございません。ご辛抱をいただき、ありがとうございます。"]]}, {"id": "store-08", "title": "エレベーター点検のお知らせ", "cat": "store", "type": "店内・施設アナウンス", "level": "TOEIC 600", "voice": "f", "s": [["Attention, customers of Bay Tower Mall.", "ベイタワーモールにお越しのお客様にご案内いたします。"], ["Elevator number 2 is under maintenance today until 4:00 P.M.", "2番エレベーターは、本日午後4:00まで点検中です。"], ["Please use the other elevators or the escalators located near the food court on each floor.", "各階のフードコート近くにある、他のエレベーターかエスカレーターをご利用ください。"], ["Customers who need help can ask a staff member at any information desk.", "お手伝いが必要なお客様は、どの案内デスクでもスタッフにお尋ねください。"], ["Our staff will gladly help you with strollers and wheelchairs.", "ベビーカーや車いすのお客様は、スタッフが喜んでお手伝いいたします。"], ["The work should be finished before the evening rush begins.", "作業は、夕方の混雑が始まる前に終わる予定です。"], ["Thank you very much for your understanding.", "ご理解のほど、よろしくお願いいたします。"]]}, {"id": "store-09", "title": "スーパーの夕方タイムセール", "cat": "store", "type": "店内・施設アナウンス", "level": "TOEIC 730", "voice": "m", "s": [["Good evening, shoppers, and welcome to the Sunny Valley Supermarket.", "こんばんは、お客様。サニーバレースーパーマーケットへようこそ。"], ["Our evening sale begins right now in the fresh food section.", "夕方のセールが、生鮮食品売り場でただいま始まります。"], ["All sushi, salads, and cooked meals are 40 percent off until closing time.", "すべてのお寿司、サラダ、お惣菜が、閉店時間まで40パーセント引きです。"], ["Today only, buy two cartons of strawberries and get a third one for free.", "本日限り、イチゴを2パックお買い上げで、3パック目が無料になります。"], ["Members of our rewards program can also earn double points on all dairy products.", "ポイントプログラムの会員様は、すべての乳製品でポイントが2倍になります。"], ["Please remember to bring your own bags, as plastic bags cost ten cents each.", "ビニール袋は1枚10セントですので、マイバッグをお持ちくださるようお願いいたします。"], ["Thank you for choosing Sunny Valley.", "サニーバレーをお選びいただき、ありがとうございます。"]]}, {"id": "store-10", "title": "店舗改装と営業時間の変更", "cat": "store", "type": "店内・施設アナウンス", "level": "TOEIC 860", "voice": "f", "s": [["Good morning, valued customers of Pinecrest Home and Garden.", "おはようございます。パインクレスト・ホーム＆ガーデンをご利用の大切なお客様へ。"], ["We are pleased to announce that our store will undergo renovations beginning the first of next month.", "来月1日から、当店の改装工事を行うことをお知らせいたします。"], ["During this time, the garden center will move to a temporary tent in the east parking lot.", "この間、ガーデンセンターは東駐車場の仮設テントに移転いたします。"], ["Business hours will be shortened to 10:00 A.M. through 6:00 P.M. while construction is in progress.", "工事期間中の営業時間は、午前10:00から午後6:00までに短縮されます。"], ["Customers with special orders may pick them up at the service desk as usual.", "特別注文のお客様は、これまでどおりサービスデスクで商品をお受け取りいただけます。"], ["In addition, all gift cards issued before the renovation will remain valid, and no expiration date will apply.", "さらに、改装前に発行されたすべてのギフトカードは引き続き有効で、有効期限はございません。"], ["We appreciate your loyalty and look forward to showing you the new store.", "日頃のご愛顧に感謝申し上げ、新しい店舗をご覧いただける日を楽しみにしております。"]]}, {"id": "vm-01", "title": "注文確認の折り返し依頼", "cat": "vm", "type": "留守番電話・伝言", "level": "TOEIC 600", "voice": "m", "s": [["Hello, Ms. Carter, this is Tom Reed from Bright Office Supply.", "こんにちは、カーターさん、ブライト・オフィス・サプライのトム・リードです。"], ["I'm calling about the order you placed yesterday for ten boxes of printer paper.", "昨日ご注文いただいたプリンター用紙10箱の件でお電話しております。"], ["Unfortunately, we only have eight boxes in stock right now.", "あいにく、現在在庫は8箱しかございません。"], ["The other two boxes will arrive next Monday.", "残りの2箱は来週月曜日に入荷する予定です。"], ["Please call me back at extension 452 and let me know if that works.", "それで問題ないか、内線452までお電話でお知らせください。"], ["Thank you, and have a good afternoon.", "ありがとうございます。よい午後をお過ごしください。"]]}, {"id": "vm-02", "title": "歯科予約の変更のお願い", "cat": "vm", "type": "留守番電話・伝言", "level": "TOEIC 730", "voice": "f", "s": [["Hi, Mr. Wilson, this is Linda from Harbor Dental Clinic calling about your appointment.", "こんにちは、ウィルソンさん、ハーバー歯科クリニックのリンダです。ご予約の件でお電話しております。"], ["Dr. Patel has been called away for an emergency on Thursday, so we need to reschedule your cleaning.", "パテル先生が木曜日に急用で不在となるため、クリーニングの予約を変更させていただく必要があります。"], ["We have openings next Tuesday at 10:30 A.M. and the following Friday at 2 P.M.", "来週火曜日の午前10時30分、またはその翌週の金曜日の午後2時でしたら空きがございます。"], ["If neither time works, we can also place you on a waiting list for earlier cancellations.", "どちらも難しい場合は、早い時間帯のキャンセル待ちリストにお入れすることも可能です。"], ["Please call our front desk at 555 0142 before the end of this week.", "今週末までに、555 0142の受付までお電話ください。"], ["We apologize for the inconvenience and look forward to seeing you soon.", "ご不便をおかけしますことをお詫び申し上げます。近いうちにお会いできるのを楽しみにしております。"]]}, {"id": "vm-03", "title": "納品遅延と代替案の連絡", "cat": "vm", "type": "留守番電話・伝言", "level": "TOEIC 860", "voice": "m", "s": [["Good morning, Ms. Nguyen, this is Daniel Brooks, the logistics coordinator at Pinecrest Furniture, returning your call from yesterday afternoon.", "おはようございます、グエンさん、パインクレスト・ファニチャーで物流を担当しているダニエル・ブルックスです。昨日の午後のお電話に折り返しております。"], ["I regret to inform you that the conference tables that were scheduled for October fourteenth have been delayed by our supplier.", "10月14日に納品予定だった会議用テーブルが、仕入先の都合で遅れていることをお知らせいたします。"], ["The new delivery date is October twenty-eighth, although we are working to move it forward if a truck becomes available.", "新しい納品日は10月28日ですが、トラックの空きが出れば前倒しできるよう調整しております。"], ["In the meantime, we can lend you twelve folding tables at no charge so that your seminar is not affected.", "それまでの間、セミナーに支障が出ないよう、折りたたみ式テーブル12台を無料でお貸しできます。"], ["Please call me at extension 318 before noon tomorrow to confirm which option you prefer.", "どちらをご希望か、明日の正午までに内線318までお電話で確認させてください。"], ["I sincerely apologize for the inconvenience this has caused your team.", "このたびはチームの皆さまにご迷惑をおかけし、誠に申し訳ございません。"]]}, {"id": "vm-04", "title": "エアコン修理の訪問時間", "cat": "vm", "type": "留守番電話・伝言", "level": "TOEIC 600", "voice": "f", "s": [["Hello, this is Karen from Cool Air Repair for Mr. Johnson in Room 305.", "もしもし、クール・エア・リペアのカレンです。305号室のジョンソンさんへの伝言です。"], ["Our technician will visit tomorrow to fix the air conditioner in your office.", "明日、技術者がオフィスのエアコンを修理に伺います。"], ["He will arrive between 9 A.M. and 11 A.M.", "午前9時から午前11時の間に到着する予定です。"], ["Please make sure someone can open the door for him.", "彼のためにドアを開けられる方がいるようにしてください。"], ["If that is a problem, call me back at extension 207.", "ご都合が悪い場合は、内線207までお電話ください。"], ["Thank you very much, and have a nice day.", "よろしくお願いいたします。よい一日をお過ごしください。"]]}, {"id": "vm-05", "title": "面接日程のご連絡", "cat": "vm", "type": "留守番電話・伝言", "level": "TOEIC 730", "voice": "m", "s": [["Hello, Ms. Rivera, this is Mark Sullivan from the human resources department at Westfield Insurance.", "こんにちは、リベラさん、ウェストフィールド保険人事部のマーク・サリバンです。"], ["Thank you for applying for the account manager position last week.", "先週は、アカウントマネージャー職にご応募いただきありがとうございました。"], ["We were impressed with your resume and would like to invite you for an interview.", "履歴書を拝見して感銘を受け、面接にお招きしたいと思っております。"], ["The interview is scheduled for Wednesday, November fourth, at 1:30 P.M. at our main office.", "面接は11月4日水曜日の午後1時30分に、本社で行います。"], ["Please bring a printed copy of your resume and a form of identification.", "履歴書を印刷したものと本人確認書類をご持参ください。"], ["Call me back at extension 126 to confirm that you can attend.", "出席できるかどうか、内線126までお電話で確認をお願いします。"], ["We look forward to meeting you.", "お会いできるのを楽しみにしております。"]]}, {"id": "vm-06", "title": "請求書の金額確認の依頼", "cat": "vm", "type": "留守番電話・伝言", "level": "TOEIC 860", "voice": "f", "s": [["Hi, Mr. Adams, this is Rachel Kim from the accounts payable team at Lakeshore Printing.", "こんにちは、アダムスさん、レイクショア印刷の買掛金チームのレイチェル・キムです。"], ["I'm calling because the invoice we received on Monday includes a charge that doesn't match the quotation we approved in September.", "月曜日に受け取った請求書に、9月に承認した見積書と一致しない料金が含まれているため、お電話しております。"], ["Specifically, the delivery fee is listed as 450 dollars, whereas the original estimate stated that shipping would be free.", "具体的には、配送料が450ドルと記載されていますが、当初の見積もりでは送料は無料とされていました。"], ["Could you please review the charge and send us a corrected invoice by the end of the week?", "この料金を確認のうえ、今週末までに修正した請求書をお送りいただけますか。"], ["Once we receive it, we will process the payment within five business days.", "受け取り次第、5営業日以内にお支払いの手続きをいたします。"], ["You can reach me directly at extension 584, or leave the details with my assistant if I'm unavailable.", "私には内線584で直接ご連絡いただけます。不在の場合は、アシスタントに詳細をお伝えください。"]]}, {"id": "vm-07", "title": "荷物の再配達について", "cat": "vm", "type": "留守番電話・伝言", "level": "TOEIC 600", "voice": "m", "s": [["Hi, this is Jim from Metro Delivery Service, and I have a package for Ms. Lopez.", "こんにちは、メトロ配送サービスのジムです。ロペスさん宛ての荷物をお預かりしています。"], ["I tried to deliver it this morning, but no one was at the front desk.", "今朝お届けにあがりましたが、受付に誰もいらっしゃいませんでした。"], ["I will come back tomorrow between 2 P.M. and 4 P.M.", "明日の午後2時から4時の間に、また伺います。"], ["If you prefer, you can pick it up at our office on Main Street.", "ご希望でしたら、メイン通りにある当社の事務所で受け取ることもできます。"], ["We are open until 6 P.M. every weekday.", "営業時間は平日の午後6時までです。"], ["Please call me at extension 291 if you have any questions.", "ご質問がありましたら、内線291までお電話ください。"]]}, {"id": "vm-08", "title": "打ち合わせ日程の変更", "cat": "vm", "type": "留守番電話・伝言", "level": "TOEIC 730", "voice": "f", "s": [["Hi, Greg, it's Susan from the marketing department, and I'm leaving you a message about tomorrow's meeting.", "こんにちは、グレッグ、マーケティング部のスーザンです。明日の会議についてメッセージを残します。"], ["The client has asked us to move it from 10 A.M. to 3 P.M. because of a conflict.", "お客様の都合が合わなくなったため、午前10時から午後3時に変更してほしいと頼まれました。"], ["I've already reserved Conference Room B for the new time.", "新しい時間に合わせて、すでに会議室Bを予約してあります。"], ["Could you bring the sales report and the updated price list?", "営業報告書と最新の価格表を持ってきていただけますか。"], ["If you can't make it at three, please call me at extension 233 as soon as possible.", "3時に来られない場合は、できるだけ早く内線233までお電話ください。"], ["Thanks a lot, and I'll see you tomorrow afternoon.", "ありがとうございます。それでは明日の午後にお会いしましょう。"]]}, {"id": "vm-09", "title": "機器修理の見積もり連絡", "cat": "vm", "type": "留守番電話・伝言", "level": "TOEIC 860", "voice": "m", "s": [["Good afternoon, Dr. Foster, this is Peter Hayes from Summit Medical Equipment, returning your call about the ultrasound machine.", "こんにちは、フォスター先生、サミット医療機器のピーター・ヘイズです。超音波装置の件でお電話をいただき、折り返しております。"], ["Our engineers have finished the inspection and found that a faulty sensor needs to be replaced.", "当社の技術者が点検を終え、故障したセンサーを交換する必要があることがわかりました。"], ["Because the warranty expired in August, the repair will cost approximately 800 dollars, including labor.", "保証が8月に切れているため、人件費を含めて修理費用はおよそ800ドルになります。"], ["If you approve the estimate by Friday, we can complete the work early next week and minimize any disruption to your patients.", "金曜日までに見積もりをご承認いただければ、来週早々に作業を完了でき、患者さまへの影響を最小限に抑えられます。"], ["In the meantime, we can arrange a loan unit, which would be delivered to your clinic by tomorrow morning.", "それまでの間、代替機を手配することも可能で、明日の朝までにクリニックにお届けいたします。"], ["Please call me back at extension 467 so that I can schedule the repair.", "修理の日程を調整しますので、内線467までお電話ください。"]]}, {"id": "vm-10", "title": "経費報告書の不備連絡", "cat": "vm", "type": "留守番電話・伝言", "level": "TOEIC 730", "voice": "f", "s": [["Hi, Kevin, this is Amy Chen from the accounting department returning your call.", "こんにちは、ケビン、経理部のエイミー・チェンです。折り返しお電話しています。"], ["I looked at the expense report you submitted for your trip to Denver.", "あなたが提出したデンバー出張の経費報告書を確認しました。"], ["It seems that the hotel receipt for the second night is missing.", "2泊目のホテルの領収書が欠けているようです。"], ["Once you scan it and send it to me, I can approve the report right away.", "スキャンして私に送っていただければ、すぐに報告書を承認できます。"], ["The deadline for this month's reimbursements is next Friday, so there is still plenty of time.", "今月の払い戻しの締め切りは来週の金曜日ですので、まだ十分に時間があります。"], ["I'll be at my desk until 5 P.M., and my extension is 340.", "午後5時まで席におりますので、内線は340です。"]]}, {"id": "mtg-01", "title": "週次会議の開始あいさつ", "cat": "mtg", "type": "社内連絡・会議", "level": "TOEIC 600", "voice": "m", "s": [["Good morning, everyone, and thank you for coming to our weekly sales meeting.", "皆さん、おはようございます。週次の営業会議にお集まりいただきありがとうございます。"], ["We have a lot to cover today, so let's get started.", "今日は話し合うことがたくさんあるので、さっそく始めましょう。"], ["First, Anna will give us an update on last month's numbers.", "まず、アンナさんが先月の数字について報告します。"], ["After that, we will discuss the new customer survey.", "その後、新しい顧客アンケートについて話し合います。"], ["Finally, we will talk about next week's schedule.", "最後に、来週のスケジュールについてお話しします。"], ["Please turn off your phones and feel free to ask questions at any time.", "携帯電話の電源を切り、質問はいつでも遠慮なくしてください。"]]}, {"id": "mtg-02", "title": "出張規定の変更のお知らせ", "cat": "mtg", "type": "社内連絡・会議", "level": "TOEIC 730", "voice": "f", "s": [["Hello, everyone, I'm Maria Gonzalez from human resources, and I'd like to announce a change to our travel policy.", "皆さん、こんにちは。人事部のマリア・ゴンザレスです。出張規定の変更をお知らせします。"], ["Starting next month, all business trips must be booked through the new online system.", "来月から、すべての出張は新しいオンラインシステムを通じて予約しなければなりません。"], ["Employees will no longer be reimbursed for tickets purchased on their own.", "ご自身で購入した航空券は、今後は払い戻しの対象外となります。"], ["Hotel stays are limited to 150 dollars per night unless a manager gives special approval.", "ホテルの宿泊費は、上司の特別な承認がない限り、1泊150ドルまでに制限されます。"], ["Detailed instructions are posted on the company intranet.", "詳しい手順は社内イントラネットに掲載されています。"], ["If you have questions, please contact my office.", "ご質問がある場合は、私のオフィスまでご連絡ください。"]]}, {"id": "mtg-03", "title": "第3四半期の業績報告", "cat": "mtg", "type": "社内連絡・会議", "level": "TOEIC 860", "voice": "m", "s": [["Thank you all for joining this quarterly review, during which I'll summarize our results for the third quarter.", "第3四半期の業績を要約する今回の四半期レビューにご参加いただき、ありがとうございます。"], ["Overall revenue rose by eight percent compared with the same period last year, driven largely by strong demand in the Midwest region.", "全体の売上は、中西部地域での強い需要に支えられ、前年同期と比べて8パーセント増加しました。"], ["However, operating costs increased by five percent, mainly because of higher shipping fees and the new warehouse lease.", "しかし、運営費は主に配送料の上昇と新しい倉庫の賃借料により、5パーセント増加しました。"], ["As a result, our profit margin narrowed slightly, which is something we need to address before the end of the year.", "その結果、利益率はわずかに縮小しており、年末までに対処する必要があります。"], ["I'll now hand over to Ms. Brown, who will present our proposals for reducing expenses.", "ここからは、経費削減の提案を発表するブラウンさんにお渡しします。"]]}, {"id": "mtg-04", "title": "新入社員の紹介とあいさつ", "cat": "mtg", "type": "社内連絡・会議", "level": "TOEIC 600", "voice": "f", "s": [["Good morning, everyone, I'd like to introduce our new team member, Jason Park.", "皆さん、おはようございます。新しいチームメンバーのジェイソン・パークさんを紹介します。"], ["Jason joins us from a software company in Seattle.", "ジェイソンさんは、シアトルのソフトウェア会社から来ました。"], ["He has five years of experience in customer support.", "彼はカスタマーサポートで5年の経験があります。"], ["He will sit next to Emily in the service department.", "彼はサービス部のエミリーさんの隣に座ります。"], ["Please say hello to him and help him feel welcome.", "ぜひ声をかけて、歓迎してあげてください。"], ["We will have a small lunch for him on Friday at noon.", "金曜日の正午に、彼のためのささやかなランチ会を開きます。"]]}, {"id": "mtg-05", "title": "社員研修のスケジュール", "cat": "mtg", "type": "社内連絡・会議", "level": "TOEIC 730", "voice": "m", "s": [["Attention, all staff, this is a reminder about the safety training scheduled for next week.", "全従業員にお知らせします。来週予定されている安全研修についてのリマインドです。"], ["Sessions will be held on Tuesday and Wednesday in the large training room on the third floor.", "研修は、火曜日と水曜日に3階の大研修室で開催されます。"], ["Employees in the production department should attend on Tuesday morning from 9 A.M. to noon.", "製造部の従業員は、火曜日の午前9時から正午まで出席してください。"], ["Everyone else will attend on Wednesday afternoon, beginning at 1 P.M.", "それ以外の全員は、水曜日の午後1時から出席します。"], ["Each session includes a short video and a hands-on demonstration.", "各セッションには、短いビデオと実演が含まれます。"], ["Please sign up using the form on the intranet by this Friday.", "今週の金曜日までに、イントラネットのフォームから申し込んでください。"], ["Attendance is mandatory, and certificates will be handed out afterward.", "出席は必須で、終了後に修了証が配られます。"]]}, {"id": "mtg-06", "title": "新オフィスへの移転計画", "cat": "mtg", "type": "社内連絡・会議", "level": "TOEIC 860", "voice": "f", "s": [["Good afternoon, everyone, I'm pleased to confirm that our department will relocate to the new office building on Harper Avenue in January.", "皆さん、こんにちは。1月に当部署がハーパー通りの新しいオフィスビルに移転することを、うれしくご報告します。"], ["The facilities team has prepared a floor plan, which shows that each team will be seated together on the fifth floor.", "施設チームがフロアプランを用意しており、各チームが5階にまとまって座ることになります。"], ["To ensure a smooth transition, please label all of your boxes and remove personal items from shared storage by December twentieth.", "スムーズな移行のため、すべての箱にラベルを付け、12月20日までに共有倉庫から私物を撤去してください。"], ["Movers will be collecting the boxes over the holiday weekend, so you won't be able to access the old building after that.", "引っ越し業者が連休中に箱を回収するため、その後は旧ビルに入ることができません。"], ["Parking permits for the new garage will be distributed next month.", "新しい駐車場の駐車許可証は、来月配布されます。"], ["We appreciate your patience and cooperation during this exciting change.", "このわくわくする変化の間、皆さまのご辛抱とご協力に感謝いたします。"]]}, {"id": "mtg-07", "title": "報告書提出の期限連絡", "cat": "mtg", "type": "社内連絡・会議", "level": "TOEIC 600", "voice": "m", "s": [["Hi, team, I just want to remind you about an important deadline.", "皆さん、こんにちは。重要な締め切りについてお知らせします。"], ["All monthly reports are due by 5 P.M. this Thursday.", "毎月の報告書はすべて、今週の木曜日の午後5時までに提出してください。"], ["Please send them to me by email, and use the new template.", "メールで私に送り、新しいテンプレートを使ってください。"], ["If you need more time, please let me know by tomorrow morning.", "もっと時間が必要な場合は、明日の朝までに知らせてください。"], ["Late reports will not be included in the management summary.", "遅れた報告書は、経営陣向けの要約に含まれません。"], ["Thank you for your hard work this month.", "今月のご尽力に感謝します。"]]}, {"id": "mtg-08", "title": "本日の会議の議題説明", "cat": "mtg", "type": "社内連絡・会議", "level": "TOEIC 730", "voice": "f", "s": [["Welcome, everyone, to the monthly planning meeting for the product development team.", "皆さん、製品開発チームの月例企画会議へようこそ。"], ["I've sent out the agenda by email, but let me go over it quickly.", "議題はメールで送りましたが、簡単に確認しましょう。"], ["We'll begin with a review of the prototype test results from last week.", "まず、先週のプロトタイプのテスト結果を確認します。"], ["Next, Tom will present the revised budget for the spring launch.", "次に、トムが春の発売に向けた修正予算を発表します。"], ["Then we'll spend about twenty minutes discussing possible delays in the production schedule.", "その後、生産スケジュールに起こり得る遅れについて、20分ほど話し合います。"], ["We need to finish by 11:30 A.M., because the conference room is booked afterward.", "会議室がその後予約されているため、午前11時30分までに終える必要があります。"], ["Please keep your comments brief so that everyone has a chance to speak.", "全員が発言できるよう、コメントは手短にお願いします。"]]}, {"id": "mtg-09", "title": "在宅勤務制度の見直し", "cat": "mtg", "type": "社内連絡・会議", "level": "TOEIC 860", "voice": "m", "s": [["Thank you for joining this brief call, which I've arranged to explain the upcoming revisions to our remote work policy.", "リモートワーク制度の今後の改定を説明するために設けたこの短い電話会議にご参加いただき、ありがとうございます。"], ["After reviewing feedback from the employee survey, the leadership team has decided to allow up to three remote days per week.", "従業員アンケートのフィードバックを検討した結果、経営陣は週に最大3日までの在宅勤務を認めることにしました。"], ["However, employees who work in customer service will be required to remain on site on Mondays because of staffing needs.", "ただし、カスタマーサービスで働く従業員は、人員配置の必要上、月曜日は出社していただく必要があります。"], ["Managers will approve each schedule individually, and any changes must be submitted at least one week in advance.", "マネージャーが各スケジュールを個別に承認し、変更は少なくとも1週間前までに提出しなければなりません。"], ["The new policy takes effect on December first, and a full document will be circulated by Friday.", "新しい制度は12月1日に施行され、完全な文書は金曜日までに配布されます。"], ["I'll stay on the line for questions.", "ご質問があれば、このまま回線に残ります。"]]}, {"id": "mtg-10", "title": "エレベーター点検のお知らせ", "cat": "mtg", "type": "社内連絡・会議", "level": "TOEIC 730", "voice": "f", "s": [["Attention, all employees, this is Helen from the building management office.", "全従業員の皆さまにお知らせします。ビル管理室のヘレンです。"], ["The elevators in the east wing will be under maintenance this Saturday from 8 A.M. to 4 P.M.", "東棟のエレベーターは、今週の土曜日の午前8時から午後4時まで点検のため停止します。"], ["If you plan to work over the weekend, please use the west wing elevators instead.", "週末に出勤される予定の方は、代わりに西棟のエレベーターをご利用ください。"], ["Employees with mobility concerns should contact the front desk in advance, and we will arrange assistance.", "移動に不安のある方は、事前に受付までご連絡いただければ、サポートを手配します。"], ["We apologize for any inconvenience this may cause.", "ご不便をおかけしますことをお詫び申し上げます。"], ["Thank you for your understanding and cooperation.", "ご理解とご協力をお願いいたします。"]]}, {"id": "ad-01", "title": "ロッシ食堂のランチ特典", "cat": "ad", "type": "広告・CM", "level": "TOEIC 600", "voice": "m", "s": [["Are you tired of the same old lunch every day?", "毎日同じランチにあきていませんか?"], ["Come to Rossi's Kitchen on Maple Street this week.", "今週はメープル通りのロッシズ・キッチンへお越しください。"], ["Every lunch special comes with a free salad and a drink.", "ランチスペシャルにはすべて、サラダとドリンクが無料でつきます。"], ["Our chef makes fresh pasta every morning.", "当店のシェフは毎朝、新鮮なパスタを作っています。"], ["This offer is valid from Monday to Friday until October 31.", "この特典は10月31日まで、月曜日から金曜日にご利用いただけます。"], ["Just show this ad to your server when you order.", "ご注文の際に、この広告を店員にお見せください。"], ["We look forward to seeing you soon!", "皆さまのお越しをお待ちしております!"]]}, {"id": "ad-02", "title": "グリーンフィットの入会特典", "cat": "ad", "type": "広告・CM", "level": "TOEIC 600", "voice": "f", "s": [["Do you want to get in shape this fall?", "この秋、体を引きしめたいと思いませんか?"], ["Join Green Fit Gym before the end of this month.", "今月末までにグリーンフィット・ジムにご入会ください。"], ["New members pay no sign-up fee.", "新規会員の方は入会金がかかりません。"], ["You will also get your first month for only 20 dollars.", "さらに、最初の1か月はたったの20ドルです。"], ["Our trainers are ready to help you every day.", "当ジムのトレーナーが毎日、お手伝いいたします。"], ["We are open from 6 A.M. to 10 P.M.", "営業時間は午前6時から午後10時までです。"], ["Visit our front desk or call us today!", "本日、受付にお越しになるか、お電話ください!"]]}, {"id": "ad-03", "title": "ホームスタイル家具セール", "cat": "ad", "type": "広告・CM", "level": "TOEIC 600", "voice": "m", "s": [["The Home Style furniture sale starts this Saturday at 9 A.M.", "ホームスタイルの家具セールは、今週土曜日の午前9時に始まります。"], ["Everything in our store is 30 percent off for two days only.", "店内の全商品が、2日間限定で30パーセント引きです。"], ["That includes sofas, dining tables, and beds.", "ソファ、ダイニングテーブル、ベッドも対象です。"], ["Free delivery is available for all orders over 500 dollars.", "500ドルを超えるご注文は、配送料が無料です。"], ["The sale ends on Sunday, November 1, at 6 P.M.", "セールは11月1日日曜日の午後6時に終了します。"], ["Come early to get the best selection.", "最良の品ぞろえをお求めなら、早めにお越しください。"], ["Home Style is located next to the Oak Park Mall.", "ホームスタイルはオークパーク・モールの隣にあります。"]]}, {"id": "ad-04", "title": "サニーデール自動車の決算セール", "cat": "ad", "type": "広告・CM", "level": "TOEIC 730", "voice": "f", "s": [["Looking for a reliable car at a fair price?", "手ごろな価格で信頼できる車をお探しですか?"], ["Sunnydale Motors is holding its year-end sale starting November 5.", "サニーデール・モータースは、11月5日から年末セールを開催します。"], ["Trade in your old vehicle, and we will give you an extra 1,000 dollars toward a new one.", "お乗りの車を下取りに出していただくと、新車の購入に使える1,000ドルを上乗せいたします。"], ["Every car comes with a three-year warranty and free oil changes for one year.", "すべての車に、3年間の保証と1年間の無料オイル交換がついています。"], ["Financing is available with an interest rate as low as two percent for qualified buyers.", "審査を通過されたお客様には、金利2パーセントからのローンをご利用いただけます。"], ["Appointments are recommended, but walk-ins are always welcome.", "ご予約をおすすめしますが、予約なしでのご来店もいつでも歓迎です。"], ["Visit our showroom on Highway 9 before the offer expires on December 15.", "特典が終了する12月15日までに、ハイウェイ9沿いのショールームへお越しください。"]]}, {"id": "ad-05", "title": "タスクフローの無料体験", "cat": "ad", "type": "広告・CM", "level": "TOEIC 730", "voice": "m", "s": [["Is your team spending too much time on paperwork?", "あなたのチームは、書類作業に時間をかけすぎていませんか?"], ["Try TaskFlow, the project management software built for busy offices.", "忙しいオフィスのために作られたプロジェクト管理ソフト、タスクフローをお試しください。"], ["Sign up this month and enjoy a free 60-day trial with no credit card required.", "今月お申し込みいただくと、クレジットカード不要で60日間の無料体験をご利用いただけます。"], ["TaskFlow lets you assign tasks, track deadlines, and share files in one place.", "タスクフローなら、作業の割り当て、期限の管理、ファイルの共有を一か所で行えます。"], ["If you subscribe for a full year, you will receive 25 percent off the regular price.", "1年間ご契約いただくと、通常価格から25パーセント割引になります。"], ["Our support team is available by chat on weekdays from 8 A.M. to 6 P.M.", "サポートチームは、平日の午前8時から午後6時までチャットで対応いたします。"], ["Visit our Web site to download the program today.", "本日、当社のウェブサイトからプログラムをダウンロードしてください。"]]}, {"id": "ad-06", "title": "マウイ島五日間の旅行プラン", "cat": "ad", "type": "広告・CM", "level": "TOEIC 730", "voice": "f", "s": [["Imagine five relaxing days on the beautiful island of Maui.", "美しいマウイ島での、のんびりとした5日間を想像してみてください。"], ["Blue Wave Travel is offering a special package for travelers who book before November 20.", "ブルーウェーブ・トラベルは、11月20日までにご予約の旅行者向けに特別パッケージをご用意しました。"], ["The price includes round-trip flights, four nights at a beachfront hotel, and daily breakfast.", "料金には、往復航空券、ビーチ沿いのホテルでの4泊、毎日の朝食が含まれています。"], ["Children under twelve stay and eat free when they share a room with their parents.", "12歳未満のお子様は、ご両親と同じお部屋なら宿泊も食事も無料です。"], ["Departures are available every Friday from January through March.", "出発は、1月から3月まで毎週金曜日にご用意しています。"], ["Cancellations made at least 14 days in advance will receive a full refund.", "14日以上前までのキャンセルには、全額を返金いたします。"], ["Call us today to reserve your seat.", "本日、お電話でお席をご予約ください。"]]}, {"id": "ad-07", "title": "チェリー歯科の新患キャンペーン", "cat": "ad", "type": "広告・CM", "level": "TOEIC 730", "voice": "m", "s": [["Do you worry about visiting the dentist?", "歯医者に行くのが心配ではありませんか?"], ["At Cherry Dental Clinic, we make every visit comfortable and quick.", "チェリー歯科クリニックでは、毎回の診察を快適かつ迅速にしています。"], ["New patients can receive a full checkup and cleaning for just 49 dollars.", "新規の患者様は、検診とクリーニングがセットでたったの49ドルです。"], ["This special price is valid until the end of December for first-time visitors.", "この特別価格は、初めてご来院の方に限り12月末までご利用いただけます。"], ["We offer evening appointments on Tuesdays and Thursdays until 8 P.M.", "火曜日と木曜日は、午後8時まで夜の診察を行っています。"], ["Most insurance plans are accepted, and payment plans are also available.", "ほとんどの保険がご利用いただけ、分割払いも可能です。"], ["Please call our front desk to book your visit today.", "本日、受付までお電話のうえ、ご予約ください。"]]}, {"id": "ad-08", "title": "メドウブルックの新店舗オープン", "cat": "ad", "type": "広告・CM", "level": "TOEIC 860", "voice": "f", "s": [["Meadowbrook Home and Garden Center, which has served this town for thirty years, will open its second location this Saturday.", "この町で30年間親しまれてきたメドウブルック・ホーム&ガーデンセンターが、今週土曜日に2号店をオープンします。"], ["Doors will open at 8 A.M. on November 7, and the first 100 customers will receive a 25 dollar gift card.", "11月7日の午前8時に開店し、先着100名のお客様に25ドルのギフトカードを差し上げます。"], ["Throughout the weekend, all plants and outdoor furniture will be discounted by up to 40 percent, while supplies last.", "週末を通して、すべての植物と屋外家具が最大40パーセント引きとなります。数に限りがございます。"], ["Our landscaping experts will also be available to offer free consultations, although advance booking is strongly recommended.", "造園の専門家による無料相談も行いますが、事前のご予約を強くおすすめします。"], ["Because we expect heavy traffic, we encourage visitors to use the shuttle service from Central Station, which runs every 15 minutes.", "混雑が予想されるため、15分おきに運行するセントラル駅からのシャトルバスのご利用をおすすめします。"], ["We hope to see you there.", "皆さまのお越しをお待ちしております。"]]}, {"id": "ad-09", "title": "ホライズン会員の年間特典", "cat": "ad", "type": "広告・CM", "level": "TOEIC 860", "voice": "m", "s": [["Horizon Business Club, the region's leading network for professionals, is now accepting new members.", "地域を代表する専門職のネットワーク、ホライズン・ビジネス・クラブは、新規会員を募集しています。"], ["Members who register before November 30 will receive complimentary access to all of our quarterly seminars, which normally cost 150 dollars each.", "11月30日までにご登録の会員様は、通常1回150ドルの四半期セミナーすべてに無料でご参加いただけます。"], ["In addition, every membership includes a private lounge at the downtown headquarters and discounted rates at partner hotels.", "さらに、会員資格には、中心街の本部にある専用ラウンジと、提携ホテルでの割引料金が含まれています。"], ["The annual fee is 400 dollars, and teams of five or more can enroll for 300 dollars per person.", "年会費は400ドルですが、5名以上のチームは1人あたり300ドルで入会できます。"], ["Please note that memberships are not transferable, and the registration deadline will not be extended under any circumstances.", "会員資格は譲渡できず、登録期限はいかなる場合も延長されませんのでご注意ください。"], ["We look forward to welcoming you to a community that values collaboration and growth.", "協力と成長を大切にするコミュニティに、皆さまをお迎えできることを楽しみにしております。"]]}, {"id": "ad-10", "title": "感謝祭ディナーのご予約案内", "cat": "ad", "type": "広告・CM", "level": "TOEIC 860", "voice": "f", "s": [["This Thanksgiving, let the chefs at Harbor View Restaurant do the cooking while you enjoy time with your family.", "この感謝祭は、料理をハーバービュー・レストランのシェフにお任せになり、ご家族との時間をお楽しみください。"], ["Our three-course dinner, which includes roast turkey and homemade pumpkin pie, will be served from noon until 8 P.M.", "ローストターキーと手作りのパンプキンパイを含む3品のコースディナーを、正午から午後8時までご提供します。"], ["Reservations are required and must be made at least three days in advance, because we expect our tables to fill quickly.", "お席がすぐに埋まると予想されるため、ご予約は必須で、少なくとも3日前までにお願いします。"], ["The price is 45 dollars for adults and 20 dollars for children under ten.", "料金は、大人45ドル、10歳未満のお子様は20ドルです。"], ["Groups of ten or more will also receive a complimentary dessert platter if they book before November 15.", "10名以上のグループは、11月15日までにご予約いただくと、デザートの盛り合わせも無料でご提供します。"], ["If you need to cancel, please notify us by November 22 to receive a full refund.", "キャンセルされる場合は、全額返金を受けるため、11月22日までにご連絡ください。"]]}, {"id": "news-01", "title": "土曜日と日曜日の天気予報", "cat": "news", "type": "ニュース・天気・交通", "level": "TOEIC 600", "voice": "m", "s": [["Good morning, and here is your weather report for Saturday.", "おはようございます。土曜日の天気予報をお伝えします。"], ["It will be cloudy in the morning with a high of 15 degrees.", "午前中はくもりで、最高気温は15度になるでしょう。"], ["Rain will start around 2 P.M. and continue through the evening.", "雨は午後2時ごろに降り始め、夜まで続くでしょう。"], ["Please take an umbrella if you plan to go out.", "お出かけの予定がある方は、傘をお持ちください。"], ["Sunday will be sunny and a little warmer.", "日曜日は晴れて、少し暖かくなるでしょう。"], ["Strong winds are expected near the coast on both days.", "両日とも、沿岸部では強い風が予想されます。"], ["Stay tuned for more updates after the news.", "ニュースのあとも、最新情報にご注目ください。"]]}, {"id": "news-02", "title": "月曜朝の道路交通情報", "cat": "news", "type": "ニュース・天気・交通", "level": "TOEIC 600", "voice": "f", "s": [["Here is your traffic report for Monday morning.", "月曜日の朝の交通情報をお伝えします。"], ["Highway 12 is very slow near the Riverside Bridge.", "リバーサイド橋付近では、ハイウェイ12がとても混んでいます。"], ["A truck broke down in the left lane at 7:15 A.M.", "午前7時15分に、左車線でトラックが故障しました。"], ["Drivers should expect a delay of about 20 minutes.", "ドライバーの方は、約20分の遅れを見込んでください。"], ["Main Street is open and moving well.", "メイン通りは通行可能で、順調に流れています。"], ["The best choice is to take Oak Avenue to downtown.", "中心街へはオーク大通りを通るのが最善です。"], ["We will give you another update in 15 minutes.", "15分後に、また最新情報をお伝えします。"]]}, {"id": "news-03", "title": "湖畔の秋祭りのお知らせ", "cat": "news", "type": "ニュース・天気・交通", "level": "TOEIC 600", "voice": "m", "s": [["The Lakeside Fall Festival will be held this Sunday in Central Park.", "レイクサイド秋祭りが、今週の日曜日にセントラル公園で開かれます。"], ["The event starts at 10 A.M. and ends at 5 P.M.", "イベントは午前10時に始まり、午後5時に終わります。"], ["There will be live music, food stands, and games for children.", "生演奏、飲食の屋台、子ども向けのゲームがあります。"], ["Admission is free for all visitors.", "入場はすべての来場者に無料です。"], ["Parking is limited, so please come by bus or bicycle.", "駐車場は限られているため、バスか自転車でお越しください。"], ["If it rains, the festival will move to the community center.", "雨の場合、祭りはコミュニティセンターに会場を移します。"], ["Local volunteers are still needed to help with the event.", "イベントを手伝う地元のボランティアを、まだ募集しています。"]]}, {"id": "news-04", "title": "エルム橋の通行止め情報", "cat": "news", "type": "ニュース・天気・交通", "level": "TOEIC 730", "voice": "f", "s": [["The city has announced that Elm Street Bridge will be closed for repairs starting next Monday.", "市は、エルム・ストリート橋が来週の月曜日から補修のため閉鎖されると発表しました。"], ["The closure is expected to last about three weeks, according to the Public Works Department.", "公共事業局によると、閉鎖は約3週間続く見込みです。"], ["Drivers heading east will be directed to Pine Road, which is two blocks to the north.", "東へ向かうドライバーは、北へ2ブロックのパイン通りへ誘導されます。"], ["Bus routes 5 and 8 will also be changed during this period.", "この期間中、バスの5番と8番の路線も変更されます。"], ["Pedestrians and cyclists may still use the bridge, but only during daytime hours.", "歩行者と自転車の方は引き続き橋を利用できますが、日中に限られます。"], ["Officials apologize for the inconvenience and ask residents to allow extra travel time.", "当局はご不便をおわびするとともに、住民の皆さまに移動時間に余裕を持つようお願いしています。"]]}, {"id": "news-05", "title": "地下鉄メトロ線のダイヤ改正", "cat": "news", "type": "ニュース・天気・交通", "level": "TOEIC 730", "voice": "m", "s": [["Starting November 9, the Metro Line subway will operate on a new weekday schedule.", "11月9日から、メトロ線の地下鉄は平日の新しいダイヤで運行されます。"], ["Trains will now arrive every six minutes during rush hour instead of every eight minutes.", "ラッシュ時の電車は、8分おきではなく6分おきに到着するようになります。"], ["The last train will leave Central Station at 11:30 P.M. rather than midnight.", "終電は、午前0時ではなく午後11時30分にセントラル駅を出発します。"], ["Weekend service will remain the same as before.", "週末の運行は、これまでと変わりません。"], ["Passengers can pick up a printed timetable at any ticket office or download one from the transit Web site.", "乗客の方は、どの切符売り場でも印刷された時刻表を受け取れ、交通局のウェブサイトからダウンロードもできます。"], ["The transit authority thanks riders for their patience during the transition.", "交通局は、移行期間中の利用者の皆さまのご協力に感謝しています。"]]}, {"id": "news-06", "title": "ブライトライン社の新工場", "cat": "news", "type": "ニュース・天気・交通", "level": "TOEIC 730", "voice": "f", "s": [["Brightline Electronics announced today that it will build a new factory in Dayton.", "ブライトライン・エレクトロニクスは本日、デイトンに新工場を建設すると発表しました。"], ["The company expects to hire about 400 workers over the next two years.", "同社は、今後2年間で約400人を雇用する見込みです。"], ["Construction will begin in March and should be finished by the end of next year.", "建設は3月に始まり、来年末までに完成する予定です。"], ["The company's president, Karen Wells, said the project will help meet growing demand for its products.", "同社の社長であるカレン・ウェルズ氏は、この計画が製品への高まる需要に応える助けになると述べました。"], ["Local leaders welcomed the news and said it would strengthen the regional economy.", "地元の指導者たちはこの知らせを歓迎し、地域経済を強化するだろうと述べました。"], ["Job applications will open on the company Web site next month.", "求人への応募は、来月、同社のウェブサイトで受け付けが始まります。"]]}, {"id": "news-07", "title": "図書館の開館時間延長", "cat": "news", "type": "ニュース・天気・交通", "level": "TOEIC 730", "voice": "m", "s": [["The Maplewood Public Library will extend its opening hours beginning next month.", "メープルウッド公共図書館は、来月から開館時間を延長します。"], ["The library will now open at 8 A.M. and close at 9 P.M. on weekdays.", "平日は、午前8時に開館し、午後9時に閉館するようになります。"], ["Library director Dr. Susan Clark said many residents had asked for evening hours.", "図書館長のスーザン・クラーク博士は、多くの住民が夜の開館を求めていたと述べました。"], ["A new study room with free Wi-Fi will also open on the second floor.", "無料Wi-Fiを備えた新しい自習室も、2階にオープンします。"], ["Residents can reserve rooms online up to seven days in advance.", "住民の方は、最大7日前までオンラインで部屋を予約できます。"], ["The library will hold a special open house on November 14.", "図書館は、11月14日に特別な見学会を開きます。"], ["Everyone in the community is invited to attend.", "地域の皆さま全員のご参加をお待ちしています。"]]}, {"id": "news-08", "title": "物流会社の合併と株価", "cat": "news", "type": "ニュース・天気・交通", "level": "TOEIC 860", "voice": "f", "s": [["Shares of Northgate Logistics rose nearly eight percent after the company announced a merger with Pacific Freight.", "ノースゲート・ロジスティクスの株価は、同社がパシフィック・フレイトとの合併を発表したあと、8パーセント近く上昇しました。"], ["The deal, which is valued at 2 billion dollars, still requires approval from regulators and shareholders.", "20億ドルと評価されるこの取引は、規制当局と株主の承認がまだ必要です。"], ["Executives said the combined company would operate more than 300 warehouses and could reduce delivery times by as much as 15 percent.", "経営陣は、統合後の会社は300を超える倉庫を運営し、配送時間を最大15パーセント短縮できる可能性があると述べました。"], ["Analysts, however, cautioned that integrating two large networks may take longer than the company currently expects.", "しかしアナリストは、2つの大きなネットワークの統合には、会社の現在の予想より時間がかかるかもしれないと注意を促しました。"], ["Chief Executive Officer Tom Reyes told reporters that no layoffs are planned in the first year following the merger.", "最高経営責任者のトム・レイエス氏は記者団に、合併後の最初の1年間は人員削減を予定していないと語りました。"], ["The companies will hold a joint press conference on Thursday at 10 A.M.", "両社は木曜日の午前10時に、合同記者会見を開きます。"]]}, {"id": "news-09", "title": "冬の嵐警報と交通への影響", "cat": "news", "type": "ニュース・天気・交通", "level": "TOEIC 860", "voice": "m", "s": [["The National Weather Service has issued a winter storm warning for the northern region, effective from midnight tonight until Friday afternoon.", "国立気象局は、北部地域に冬の嵐警報を発令しました。今夜の午前0時から金曜日の午後まで有効です。"], ["Forecasters predict that up to 12 inches of snow could accumulate in higher elevations, making travel extremely hazardous.", "予報官は、標高の高い地域で最大12インチの雪が積もり、移動が極めて危険になるおそれがあると予測しています。"], ["Several school districts have already announced that classes will be canceled on Thursday, and others are expected to follow.", "いくつかの学区はすでに木曜日の授業の中止を発表しており、ほかの学区も続く見込みです。"], ["State officials urge residents to avoid unnecessary driving, and drivers who must travel should carry blankets, water, and a flashlight.", "州当局は住民に不要な運転を控えるよう求めており、移動が必要なドライバーは毛布、水、懐中電灯を携帯してください。"], ["Airport authorities have warned that departures may be delayed or canceled, so passengers should check their flight status first.", "空港当局は出発便が遅れたり欠航したりする可能性があると警告しており、乗客はまず運航状況を確認してください。"], ["Temperatures are expected to return to normal by the weekend.", "気温は、週末までに平年並みに戻る見込みです。"]]}, {"id": "news-10", "title": "地域交通の運賃改定発表", "cat": "news", "type": "ニュース・天気・交通", "level": "TOEIC 860", "voice": "f", "s": [["The Valley Regional Transit Authority announced that fares will rise by an average of ten percent starting January 1.", "バレー地域交通局は、1月1日から運賃が平均10パーセント値上がりすると発表しました。"], ["Officials explained that the increase will fund the replacement of aging trains, which have caused frequent delays.", "当局は、この値上げが、たびたび遅延を引き起こしてきた老朽化した電車の入れ替えに充てられると説明しました。"], ["To offset the higher prices, the authority will introduce a monthly pass that allows unlimited rides on all routes for 90 dollars.", "値上げを補うため、同局は、全路線で乗り放題となる90ドルの月間パスを導入します。"], ["Students and senior citizens will continue to receive half-price tickets, provided that they show a valid identification card.", "学生と高齢者は、有効な身分証明書を提示すれば、引き続き半額の切符を利用できます。"], ["A public hearing will take place at City Hall on November 18, where residents may share their opinions.", "11月18日に市役所で公聴会が開かれ、住民は意見を述べることができます。"]]}, {"id": "tour-01", "title": "市立博物館の見学案内", "cat": "tour", "type": "ツアー・施設案内", "level": "TOEIC 600", "voice": "m", "s": [["Good morning, everyone, and welcome to the Riverside City Museum.", "皆さん、おはようございます。リバーサイド市立博物館へようこそ。"], ["My name is Tom, and I will be your guide today.", "私はトムと申します。本日のガイドを務めます。"], ["The tour will take about 60 minutes, and we will start in the main hall.", "ツアーは約60分で、メインホールから始めます。"], ["Please do not touch the displays, and photos are allowed without a flash.", "展示品には触れないでください。写真はフラッシュなしであれば撮影できます。"], ["If you need a break, there are benches near the elevator.", "休憩が必要でしたら、エレベーターの近くにベンチがあります。"], ["We will meet again at the gift shop at 11:30 A.M.", "午前11時30分にギフトショップで再び集合します。"]]}, {"id": "tour-02", "title": "工場見学の注意事項", "cat": "tour", "type": "ツアー・施設案内", "level": "TOEIC 600", "voice": "f", "s": [["Welcome to the Greenfield Bread Factory, and thank you for visiting us today.", "グリーンフィールド・パン工場へようこそ。本日はご来場ありがとうございます。"], ["Before we go inside, please put on the hairnets and white coats on the table.", "中に入る前に、テーブルの上のヘアネットと白衣を着用してください。"], ["Please keep your hands out of your pockets while we walk.", "歩いている間は、ポケットから手を出しておいてください。"], ["You may take pictures, but please do not touch any of the machines.", "写真撮影は可能ですが、機械には一切触れないでください。"], ["The tour is about 45 minutes, and then you can taste fresh bread.", "ツアーは約45分で、その後に焼きたてのパンを試食できます。"], ["If you cannot hear me, please raise your hand.", "私の声が聞こえない場合は、手を挙げてください。"]]}, {"id": "tour-03", "title": "市内バスツアーの出発", "cat": "tour", "type": "ツアー・施設案内", "level": "TOEIC 600", "voice": "m", "s": [["Good afternoon, and welcome aboard the Harbor City bus tour.", "こんにちは。ハーバーシティ・バスツアーへようこそご乗車くださいました。"], ["Please find a seat and fasten your seat belt.", "お座席をお探しになり、シートベルトをお締めください。"], ["We will make three stops, and each stop will be about 20 minutes.", "停車は3か所で、各停車は約20分です。"], ["The bus will leave the first stop at 2:15 P.M. sharp.", "バスは最初の停車地を午後2時15分ちょうどに出発します。"], ["Please be back at the bus five minutes before departure.", "出発の5分前にはバスにお戻りください。"], ["Free bottled water is in the front, so please help yourself.", "前方に無料のペットボトルの水がありますので、ご自由にお取りください。"], ["Please ask me if you have any questions along the way.", "道中でご質問があれば、何でも私におたずねください。"]]}, {"id": "tour-04", "title": "植物園のガイドツアー", "cat": "tour", "type": "ツアー・施設案内", "level": "TOEIC 730", "voice": "f", "s": [["Welcome to the Maple Grove Botanical Garden, where more than two thousand types of plants are on display.", "2000種類以上の植物が展示されているメープルグローブ植物園へようこそ。"], ["Our walking tour begins at the main gate and ends at the tea house near the lake.", "ウォーキングツアーは正門から始まり、湖の近くの茶屋で終わります。"], ["Because the spring flowers are at their peak, the paths may be crowded this morning.", "春の花が見頃を迎えているため、今朝は園路が混雑する可能性があります。"], ["Please stay on the marked trails to protect the plants, and do not pick any flowers.", "植物を守るため、印のついた道から外れず、花を摘まないでください。"], ["Strollers are welcome, but the east path is closed for repairs until noon.", "ベビーカーのご利用は歓迎ですが、東側の道は正午まで補修工事のため閉鎖されています。"], ["After the tour, you are free to explore until the garden closes at 5:00 P.M.", "ツアーの後は、午後5時の閉園まで自由に散策していただけます。"]]}, {"id": "tour-05", "title": "歴史的建造物の見学", "cat": "tour", "type": "ツアー・施設案内", "level": "TOEIC 730", "voice": "m", "s": [["Thank you for joining the tour of the Whitmore House, which was built in 1895.", "1895年に建てられたホイットモア邸のツアーにご参加いただきありがとうございます。"], ["This building was restored last year, so some rooms are still being repaired.", "この建物は昨年修復されましたが、一部の部屋はまだ補修中です。"], ["Please wear the soft shoe covers we provided, because the wooden floors are easy to scratch.", "木の床は傷つきやすいので、こちらでご用意した柔らかい靴カバーを着用してください。"], ["Large bags must be left in the lockers by the entrance.", "大きな荷物は、入口横のロッカーに預けていただく必要があります。"], ["The tour is limited to 12 people, so we will start on time at 10:00 A.M.", "ツアーは12名限定ですので、午前10時ちょうどに開始いたします。"], ["If anyone needs assistance with the stairs, please let me know at the beginning.", "階段で介助が必要な方は、最初にお知らせください。"]]}, {"id": "tour-06", "title": "ワイナリーの試飲ツアー", "cat": "tour", "type": "ツアー・施設案内", "level": "TOEIC 730", "voice": "f", "s": [["Welcome to Sunny Ridge Winery, and thank you for reserving a spot on our afternoon tour.", "サニーリッジ・ワイナリーへようこそ。午後のツアーをご予約いただきありがとうございます。"], ["First, we will walk through the vineyard, and then we will visit the barrel room.", "まずブドウ畑を歩き、その後で樽の貯蔵室を見学します。"], ["The tasting will take place at 3:30 P.M. in the garden, weather permitting.", "試飲は、天候が許せば午後3時30分に庭で行います。"], ["Guests must be at least 21 years old, so please be ready to show your driver's license.", "ご参加には21歳以上である必要がありますので、運転免許証をご提示できるようご準備ください。"], ["Bottles can be purchased at the shop, and shipping is free for orders over 100 dollars.", "ボトルは売店でご購入いただけ、100ドルを超えるご注文は送料無料です。"], ["Please drink water between samples, and ask me anything you like.", "試飲の合間には水を飲み、何でも私におたずねください。"]]}, {"id": "tour-07", "title": "大学キャンパスの案内", "cat": "tour", "type": "ツアー・施設案内", "level": "TOEIC 730", "voice": "m", "s": [["Welcome to Lakeside University, and congratulations on joining our incoming class.", "レイクサイド大学へようこそ。新入生の仲間入りおめでとうございます。"], ["This orientation walk will take about an hour, and we will visit six buildings.", "このオリエンテーションウォークは約1時間で、6つの建物を訪れます。"], ["Our first stop is the library, where you can pick up your student card.", "最初の立ち寄り先は図書館で、そこで学生証を受け取れます。"], ["Please note that the cafeteria will be closed today for cleaning, but food trucks are parked outside.", "本日は清掃のためカフェテリアが閉まっていますが、外にフードトラックが止まっています。"], ["If you get separated from the group, meet us at the clock tower at noon.", "グループからはぐれた場合は、正午に時計塔で私たちと合流してください。"], ["Group leaders will hand out campus maps as soon as we reach the student center.", "学生センターに着き次第、グループリーダーがキャンパスマップを配ります。"]]}, {"id": "tour-08", "title": "美術館の特別展ツアー", "cat": "tour", "type": "ツアー・施設案内", "level": "TOEIC 860", "voice": "f", "s": [["Good morning, and thank you for attending this preview of the Coastal Light exhibition, which opens to the public next Monday.", "おはようございます。来週月曜日に一般公開されるコースタル・ライト展の内覧会にご参加いただきありがとうございます。"], ["Because many of the paintings on loan are extremely fragile, please remain behind the yellow line at all times.", "貸出作品の多くは非常に壊れやすいため、常に黄色い線の後ろにお下がりください。"], ["The curator, who spent nearly three years organizing this collection, will join us in the third gallery.", "このコレクションの準備に3年近くを費やした学芸員が、第3展示室で私たちに加わります。"], ["The audio guides, which are available in five languages, must be returned before you leave the building.", "5言語でご利用いただけるオーディオガイドは、退館前に必ずご返却ください。"], ["Should you wish to extend your visit, the museum café will remain open until 6:00 P.M.", "滞在を延ばされたい場合は、美術館のカフェが午後6時まで営業しています。"], ["We will reconvene at the main entrance at 11:45 A.M. to complete the feedback survey.", "午前11時45分に正面入口で再集合し、アンケートにご記入いただきます。"]]}, {"id": "tour-09", "title": "製造工場の見学ルール", "cat": "tour", "type": "ツアー・施設案内", "level": "TOEIC 860", "voice": "m", "s": [["Welcome to Delmar Precision Manufacturing, where we produce components for medical equipment used in hospitals nationwide.", "全国の病院で使われる医療機器の部品を製造しているデルマー精密製造へようこそ。"], ["For safety reasons, all visitors must wear protective glasses and earplugs, which are located in the basket beside me.", "安全のため、すべての見学者は保護メガネと耳栓を着用する必要があります。私の横のかごにございます。"], ["Please remain within the green walkway, since forklifts that transport heavy materials operate throughout the facility.", "重い資材を運ぶフォークリフトが施設内を走行しているため、緑色の通路から出ないでください。"], ["Photography is strictly prohibited on the production floor, as some of our processes are protected by patents.", "一部の工程は特許で保護されているため、製造現場での撮影は固く禁止されています。"], ["The entire tour should last approximately 75 minutes, after which lunch will be served in the visitor lounge.", "ツアー全体は約75分で、その後、来訪者ラウンジで昼食をご用意します。"], ["Anyone who feels unwell at any point should notify me immediately so that we can arrange assistance.", "体調が悪くなった方は、対応を手配できるよう、すぐに私にお知らせください。"]]}, {"id": "tour-10", "title": "歴史地区の徒歩ガイド", "cat": "tour", "type": "ツアー・施設案内", "level": "TOEIC 860", "voice": "f", "s": [["Thank you all for joining the Old Harbor walking tour, which departs from the fountain at exactly 10:00 A.M.", "オールド・ハーバー・ウォーキングツアーにご参加いただきありがとうございます。午前10時ちょうどに噴水前から出発します。"], ["Throughout the next two hours, we will explore neighborhoods that were once the center of the shipping industry.", "これから2時間かけて、かつて海運業の中心だった地区を巡ります。"], ["Since the cobblestone streets can be uneven, I strongly recommend that you wear comfortable shoes.", "石畳の道は凹凸があるため、歩きやすい靴を履かれることを強くお勧めします。"], ["We will pause at the maritime museum, where tickets that you have already received will grant you entry.", "海洋博物館で立ち止まります。すでにお受け取りのチケットで入場できます。"], ["Should it begin to rain, the tour will continue under cover, though we may need to adjust the route.", "雨が降り始めた場合は屋根のある場所でツアーを続けますが、ルートを調整する可能性があります。"], ["The tour concludes at a local café, where each guest is invited to enjoy a complimentary coffee.", "ツアーは地元のカフェで終了し、お客様全員に無料のコーヒーをご用意しています。"]]}, {"id": "event-01", "title": "会議の開会あいさつ", "cat": "event", "type": "イベント・講演", "level": "TOEIC 600", "voice": "m", "s": [["Good morning, everyone, and welcome to the Annual Sales Conference.", "皆さん、おはようございます。年次営業会議へようこそ。"], ["We have a full schedule today, so I will keep my remarks short.", "本日は予定が詰まっていますので、私のあいさつは手短にします。"], ["The first session starts at 9:30 A.M. in Room B.", "最初のセッションは午前9時30分にB会議室で始まります。"], ["Lunch will be served at noon in the main lobby.", "昼食は正午にメインロビーでご用意します。"], ["Please turn off your phones during the presentations.", "発表中は携帯電話の電源をお切りください。"], ["Name tags are available at the front desk if you have not picked one up.", "まだ名札をお取りでない方は、受付にご用意しています。"], ["Thank you, and I hope you enjoy the day.", "ありがとうございます。どうぞ一日をお楽しみください。"]]}, {"id": "event-02", "title": "講演会の講演者紹介", "cat": "event", "type": "イベント・講演", "level": "TOEIC 600", "voice": "f", "s": [["Good evening, and thank you for coming to tonight's lecture.", "こんばんは。本日の講演会にお越しいただきありがとうございます。"], ["Our speaker today is Dr. Helen Brooks from Pine Valley College.", "本日の講演者は、パインバレー大学のヘレン・ブルックス博士です。"], ["She has studied city planning for more than 20 years.", "博士は20年以上にわたり都市計画を研究してこられました。"], ["Her new book, Cities of Tomorrow, will be on sale after the talk.", "新著の「明日の都市」は、講演の後に販売されます。"], ["She will speak for 40 minutes, and then we will take questions.", "博士は40分間お話しされ、その後質疑応答を行います。"], ["Please join me in giving a warm welcome to Dr. Brooks.", "どうぞ温かい拍手でブルックス博士をお迎えください。"]]}, {"id": "event-03", "title": "ワークショップの連絡", "cat": "event", "type": "イベント・講演", "level": "TOEIC 600", "voice": "m", "s": [["Welcome to the writing workshop, and thank you for signing up.", "ライティング・ワークショップへようこそ。お申し込みありがとうございます。"], ["Please take a seat at one of the tables and pick up a folder.", "いずれかのテーブルにお座りになり、フォルダーを一つお取りください。"], ["Inside the folder, you will find a pen, a notebook, and today's schedule.", "フォルダーの中には、ペン、ノート、本日のスケジュールが入っています。"], ["We will work in small groups from 10:00 A.M. until noon.", "午前10時から正午まで、少人数のグループで作業します。"], ["There will be a coffee break at 11:00 A.M. in the hallway.", "午前11時に廊下でコーヒーブレイクがあります。"], ["If you have any trouble, please raise your hand and a helper will come.", "お困りの際は手を挙げてください。スタッフが参ります。"]]}, {"id": "event-04", "title": "表彰式の開式あいさつ", "cat": "event", "type": "イベント・講演", "level": "TOEIC 730", "voice": "f", "s": [["Good evening, ladies and gentlemen, and welcome to the 15th Annual Employee Awards Dinner.", "皆様、こんばんは。第15回年次社員表彰ディナーへようこそ。"], ["Tonight, we will recognize ten people who made an outstanding contribution to our company this year.", "今夜は、今年当社に顕著な貢献をした10名を表彰します。"], ["Each winner will receive a trophy and a gift card from our president.", "受賞者の皆様には、社長からトロフィーとギフトカードが贈られます。"], ["Dinner will be served first, and the awards will begin at 7:30 P.M.", "まず夕食をお出しし、表彰は午後7時30分に始まります。"], ["Please remain seated while the winners walk up to the stage.", "受賞者がステージに上がる間は、着席のままでお願いします。"], ["We are very proud of every one of you, and we thank you for your hard work.", "皆様一人ひとりを誇りに思っております。日頃のご尽力に感謝いたします。"]]}, {"id": "event-05", "title": "チャリティ募金イベント", "cat": "event", "type": "イベント・講演", "level": "TOEIC 730", "voice": "m", "s": [["Thank you for being here tonight to support the Hope Children's Fund.", "本日はホープ子ども基金を支援するためにお越しいただき、ありがとうございます。"], ["Last year, your donations helped us build two new libraries in rural areas.", "昨年は、皆様のご寄付により、地方に2つの新しい図書館を建てることができました。"], ["This year, our goal is to raise 50 thousand dollars by the end of the evening.", "今年は、今夜のうちに5万ドルを集めることが目標です。"], ["You can donate by filling out the card on your table or by speaking to a volunteer.", "寄付は、テーブルの上のカードにご記入いただくか、ボランティアにお声がけください。"], ["Every gift, no matter how small, will make a real difference.", "どんなに小さな寄付でも、必ず大きな違いを生み出します。"], ["The silent auction closes at 9:00 P.M., so please place your bids soon.", "サイレントオークションは午後9時に締め切りますので、お早めに入札してください。"]]}, {"id": "event-06", "title": "新製品発表イベント", "cat": "event", "type": "イベント・講演", "level": "TOEIC 730", "voice": "f", "s": [["Welcome to the launch of the Zenith 5 smartwatch, the most exciting product we have ever made.", "当社がこれまでに作った中で最も画期的な製品、ゼニス5スマートウォッチの発表会へようこそ。"], ["It has a longer battery life, a brighter screen, and a much lighter design.", "バッテリーはより長持ちし、画面はより明るく、デザインはずっと軽くなっています。"], ["After my presentation, you will have a chance to try one yourself at the demo tables.", "私のプレゼンテーションの後、デモテーブルで実際に試していただけます。"], ["The watch will go on sale on March 3, and it will cost 199 dollars.", "この腕時計は3月3日に発売され、価格は199ドルです。"], ["Anyone who orders online today will receive a free charging stand.", "本日オンラインでご注文の方には、充電スタンドを無料で差し上げます。"], ["Now, let me show you what makes this device so special.", "それでは、この製品のどこが特別なのかをご覧いただきます。"]]}, {"id": "event-07", "title": "大学卒業式での祝辞", "cat": "event", "type": "イベント・講演", "level": "TOEIC 730", "voice": "m", "s": [["Good morning, graduates, families, and friends, and congratulations to the Class of 2026.", "卒業生、ご家族、ご友人の皆様、おはようございます。2026年度の卒業生の皆さん、おめでとうございます。"], ["Four years ago, many of you walked into this hall feeling nervous and unsure about the future.", "4年前、皆さんの多くは、緊張し、将来に不安を抱えながらこのホールに足を踏み入れました。"], ["Today, you leave with new skills, lasting friendships, and a degree that you earned.", "今日、皆さんは新しい技能と生涯の友情、そして自らの力で得た学位を手に巣立ちます。"], ["Please remember to keep learning, even after you leave this campus.", "このキャンパスを離れた後も、学び続けることを忘れないでください。"], ["After the ceremony, photos will be taken on the front lawn, and a reception will follow in the gym.", "式の後は、前庭で写真撮影があり、続いて体育館でレセプションが行われます。"], ["Once again, congratulations, and the best of luck to all of you.", "改めて、おめでとうございます。皆さんのご多幸をお祈りします。"]]}, {"id": "event-08", "title": "見本市ブースの案内放送", "cat": "event", "type": "イベント・講演", "level": "TOEIC 860", "voice": "f", "s": [["Attention, visitors to the Global Home Expo, and thank you for stopping by the Brightway Appliances booth in Hall C.", "グローバル・ホーム・エキスポにご来場の皆様、C館のブライトウェイ家電ブースにお立ち寄りいただきありがとうございます。"], ["Every hour, we demonstrate our newest refrigerator, which uses nearly 30 percent less electricity than last year's model.", "毎時、昨年のモデルより電力使用量が約30パーセント少ない最新の冷蔵庫をデモンストレーションしています。"], ["Those who register at our booth before 3:00 P.M. will be entered in a drawing for a free washing machine.", "午後3時までに当ブースで登録された方は、洗濯機が当たる抽選に参加できます。"], ["Catalogs are available from any of our representatives, who will gladly assist you.", "カタログは、喜んでご案内する当社の担当者のどなたからでもお受け取りいただけます。"], ["Please note that the next demonstration, which was originally scheduled for 2:00 P.M., has been moved to 2:30 P.M.", "当初午後2時に予定していた次のデモンストレーションは、午後2時30分に変更になりましたのでご了承ください。"], ["We apologize for any inconvenience this change may cause, and we appreciate your patience.", "この変更によりご不便をおかけしましたことをおわびし、ご理解に感謝いたします。"]]}, {"id": "event-09", "title": "国際会議の開会あいさつ", "cat": "event", "type": "イベント・講演", "level": "TOEIC 860", "voice": "m", "s": [["On behalf of the organizing committee, it is my great pleasure to welcome you to the International Logistics Forum.", "組織委員会を代表して、国際物流フォーラムへの皆様のご来場を心より歓迎いたします。"], ["More than 800 professionals from 30 countries have registered, which makes this the largest gathering in our history.", "30か国から800名を超える専門家が登録されており、当フォーラム史上最大の集まりとなります。"], ["Over the next three days, we will examine how emerging technologies are reshaping global supply chains.", "これから3日間、新たな技術が世界のサプライチェーンをどう変えつつあるかを検討します。"], ["The program has been revised slightly, so please check the updated schedule that was emailed to you this morning.", "プログラムが一部変更されましたので、今朝メールでお送りした最新の日程をご確認ください。"], ["Shuttle buses, which run every 15 minutes, will take attendees between the convention center and the partner hotels.", "15分おきに運行するシャトルバスが、コンベンションセンターと提携ホテルの間を参加者の皆様にご利用いただけます。"], ["I trust that you will find these sessions both informative and rewarding.", "これらのセッションが、有益で実り多いものとなることを確信しております。"]]}, {"id": "event-10", "title": "基調講演者の紹介", "cat": "event", "type": "イベント・講演", "level": "TOEIC 860", "voice": "f", "s": [["It is an honor to introduce this morning's keynote speaker, Mr. David Carter, who founded Northline Software twelve years ago.", "12年前にノースライン・ソフトウェアを創業した、本日午前の基調講演者デビッド・カーター氏をご紹介できることを光栄に思います。"], ["Under his leadership, the company has grown from a team of five into an organization that employs over two thousand people.", "氏のリーダーシップのもと、同社は5人のチームから2000人以上を雇用する組織へと成長しました。"], ["Mr. Carter, who recently received an award for innovation, will discuss how companies can adapt to rapid change.", "最近イノベーション賞を受賞したカーター氏は、企業が急速な変化にどう適応できるかをお話しされます。"], ["His presentation will last about 45 minutes, and a question and answer session will follow.", "講演は約45分で、その後に質疑応答の時間があります。"], ["Those who wish to ask a question are kindly requested to line up at the microphones near the aisle.", "ご質問のある方は、通路付近のマイクの前にお並びください。"], ["Please give a warm welcome to Mr. David Carter.", "温かい拍手でデビッド・カーター氏をお迎えください。"]]}, {"id": "phone-01", "title": "銀行の自動音声案内", "cat": "phone", "type": "電話・自動音声", "level": "TOEIC 600", "voice": "m", "s": [["Thank you for calling Maple Valley Bank.", "メープルバレー銀行にお電話いただき、ありがとうございます。"], ["Our branches are open from 9:00 A.M. to 5:00 P.M., Monday through Friday.", "当行の支店は、月曜日から金曜日の午前9時から午後5時まで営業しております。"], ["To check your account balance, please press one.", "口座残高の照会は、1を押してください。"], ["To report a lost or stolen card, press two.", "カードの紛失や盗難のご連絡は、2を押してください。"], ["If you would like to speak with a customer service representative, please press three.", "お客様サービス担当者とお話しになりたい場合は、3を押してください。"], ["Please stay on the line, and your call will be answered in the order it was received.", "このままお待ちください。お電話は受け付けた順にお取りいたします。"]]}, {"id": "phone-02", "title": "歯科医院の予約確認", "cat": "phone", "type": "電話・自動音声", "level": "TOEIC 600", "voice": "f", "s": [["Hello, this is a message from Greenfield Dental Clinic.", "もしもし、グリーンフィールド歯科医院からのメッセージです。"], ["We are calling to confirm your appointment with Dr. Parker.", "パーカー先生とのご予約の確認でお電話しております。"], ["Your appointment is tomorrow at 10:30 A.M.", "ご予約は明日の午前10時30分です。"], ["Please arrive ten minutes early so that you can fill out a short form.", "短い用紙にご記入いただくため、10分前にお越しください。"], ["Please bring your insurance card with you.", "保険証をお持ちください。"], ["If you need to change your appointment, please call us back before noon today.", "ご予約を変更される場合は、本日正午までにお電話ください。"], ["We look forward to seeing you.", "お会いできるのを楽しみにしております。"]]}, {"id": "phone-03", "title": "電話の保留メッセージ", "cat": "phone", "type": "電話・自動音声", "level": "TOEIC 600", "voice": "m", "s": [["Thank you for holding while we help other customers.", "他のお客様の対応中、お待ちいただきありがとうございます。"], ["All of our agents are currently assisting other callers.", "現在、すべての担当者が他のお客様に対応しております。"], ["Your estimated wait time is about five minutes, according to our system.", "システムによると、お待ちいただく時間はおよそ5分です。"], ["You can also visit our Web site to track your order.", "当社のウェブサイトでもご注文の状況をご確認いただけます。"], ["We appreciate your patience and apologize for the delay.", "お待たせしておりますことをお詫びし、ご辛抱に感謝いたします。"], ["Please stay on the line, and the next available agent will assist you.", "このままお待ちください。次に空いた担当者がご対応いたします。"]]}, {"id": "phone-04", "title": "停電に関するお知らせ", "cat": "phone", "type": "電話・自動音声", "level": "TOEIC 730", "voice": "f", "s": [["This is a service notice from Riverside Electric.", "こちらはリバーサイド電力からのサービスのお知らせです。"], ["Due to a storm last night, some customers in the Oakdale area are without power.", "昨夜の嵐の影響で、オークデール地区の一部のお客様が停電しております。"], ["Our repair crews are working as quickly as possible to fix the problem.", "修理班が、問題の解決に向けてできる限り迅速に作業を行っております。"], ["We expect electricity to be restored by 6:00 P.M. this evening.", "本日夕方の午後6時までに電気が復旧する見込みです。"], ["We sincerely apologize for the inconvenience this outage has caused.", "この停電によるご不便を心よりお詫び申し上げます。"], ["To report a new outage or get an update, please press one.", "新たな停電のご連絡や最新情報をお聞きになるには、1を押してください。"]]}, {"id": "phone-05", "title": "航空会社の運航情報", "cat": "phone", "type": "電話・自動音声", "level": "TOEIC 730", "voice": "m", "s": [["Thank you for calling Skyline Airways flight information.", "スカイライン航空の運航情報にお電話いただき、ありがとうございます。"], ["Flight 482 to Denver has been delayed because of heavy fog at the airport.", "デンバー行き482便は、空港の濃霧のため遅延しております。"], ["The new departure time is 3:45 P.M. from gate twelve.", "新しい出発時刻は午後3時45分で、12番ゲートから出発します。"], ["Passengers who miss a connecting flight will be rebooked at no extra charge.", "乗り継ぎ便に間に合わなかったお客様は、追加料金なしで再予約いたします。"], ["Please check the monitors in the terminal for the latest updates.", "最新の情報は、ターミナル内のモニターでご確認ください。"], ["We apologize for any inconvenience this delay may cause you.", "この遅延によりご迷惑をおかけしますことをお詫び申し上げます。"]]}, {"id": "phone-06", "title": "病院の診療時間案内", "cat": "phone", "type": "電話・自動音声", "level": "TOEIC 730", "voice": "f", "s": [["You have reached the Hillcrest Medical Center, family care department.", "ヒルクレスト医療センター、家庭医療科にお電話いただきました。"], ["Our office is open Monday through Thursday from 8:00 A.M. to 6:00 P.M.", "当院は、月曜日から木曜日の午前8時から午後6時まで診療しております。"], ["On Fridays, we close at noon, and we are closed on weekends.", "金曜日は正午に終了し、週末は休診です。"], ["If this is a medical emergency, please hang up and call your local emergency number.", "緊急の場合は、電話を切って、お住まいの地域の緊急番号におかけください。"], ["To schedule an appointment, press one, and to refill a prescription, press two.", "ご予約は1を、処方薬の再処方は2を押してください。"], ["For all other questions, please stay on the line for the next available receptionist.", "その他のご質問は、このままお待ちいただき、次に空いた受付係におつなぎいたします。"]]}, {"id": "phone-07", "title": "ガス料金の自動案内", "cat": "phone", "type": "電話・自動音声", "level": "TOEIC 730", "voice": "m", "s": [["Welcome to the automated billing line for Summit Gas and Water.", "サミット・ガス・水道の自動料金案内ダイヤルへようこそ。"], ["Your current bill of 82 dollars is due on March fifteenth.", "現在のご請求額82ドルのお支払い期限は、3月15日です。"], ["To avoid a late fee, please make your payment before that date.", "延滞料金を避けるため、その日までにお支払いください。"], ["You can pay by phone, online, or by mail using the envelope that came with your bill.", "お支払いは、電話、オンライン、または請求書に同封された封筒を使った郵送でも可能です。"], ["If you have already paid, please disregard this message.", "すでにお支払い済みの場合は、このメッセージを無視してください。"], ["To hear these options again, press the star key.", "これらの案内をもう一度お聞きになるには、スターキーを押してください。"]]}, {"id": "phone-08", "title": "宅配業者の再配達案内", "cat": "phone", "type": "電話・自動音声", "level": "TOEIC 860", "voice": "f", "s": [["Thank you for calling Harbor Parcel Service, where your satisfaction is our highest priority.", "お客様の満足を最優先に考えるハーバー・パーセル・サービスにお電話いただき、ありがとうございます。"], ["Because of unusually high shipping volume during the holiday season, some deliveries may arrive one to two days late.", "休暇シーズンの荷物量が例年になく多いため、一部の配達が1日から2日遅れる可能性があります。"], ["If you have a tracking number, you can enter it now to hear the current status of your package.", "追跡番号をお持ちの場合は、今入力していただくと、お荷物の現在の状況をお聞きいただけます。"], ["Customers who are eligible for a refund of the shipping fee will receive an automatic credit within seven business days.", "送料の返金対象となるお客様には、7営業日以内に自動的に返金されます。"], ["To arrange a redelivery at a more convenient time, please press two, and we will confirm your preferred window.", "より都合のよい時間に再配達を手配するには、2を押してください。ご希望の時間帯を確認いたします。"], ["We truly appreciate your understanding as our team works to resolve this backlog.", "当社チームがこの遅れの解消に努めておりますので、ご理解いただけますようお願い申し上げます。"]]}, {"id": "phone-09", "title": "ホテルの予約変更案内", "cat": "phone", "type": "電話・自動音声", "level": "TOEIC 860", "voice": "m", "s": [["You have reached the reservations office at the Lakeview Grand Hotel, which is currently closed.", "レイクビュー・グランドホテルの予約窓口にお電話いただきましたが、現在は営業時間外です。"], ["Our front desk is staffed from 7:00 A.M. until 11:00 P.M., and reservations can be modified during those hours.", "フロントは午前7時から午後11時まで対応しており、ご予約の変更はその時間内に承ります。"], ["If you are calling about an existing booking, please have your confirmation number ready before you speak with an agent.", "すでにあるご予約についてのお電話の場合は、担当者とお話しになる前に確認番号をご用意ください。"], ["Cancellations made at least 48 hours before check-in will be fully refunded to the original form of payment.", "チェックインの48時間以上前までのキャンセルは、元のお支払い方法に全額返金されます。"], ["Guests who wish to extend their stay should know that availability depends on upcoming events.", "滞在の延長をご希望のお客様は、空室状況が今後のイベントによって左右されることをご承知おきください。"], ["Otherwise, please leave your name and number after the tone, and we will return your call promptly.", "それ以外の場合は、発信音の後にお名前と電話番号を残してください。折り返しすぐにご連絡いたします。"]]}, {"id": "phone-10", "title": "店舗の営業時間案内", "cat": "phone", "type": "電話・自動音声", "level": "TOEIC 860", "voice": "f", "s": [["Thank you for calling Westbrook Home and Garden, your neighborhood source for home improvement supplies.", "住まいの改装用品を扱う地域のお店、ウエストブルック・ホーム・アンド・ガーデンにお電話いただき、ありがとうございます。"], ["Beginning next month, our main store on Elm Street will extend its weekday hours and remain open until 9:00 P.M.", "来月から、エルム通りの本店は平日の営業時間を延長し、午後9時まで営業いたします。"], ["Weekend hours will stay the same, with doors opening at 8:00 A.M. on Saturdays and 10:00 A.M. on Sundays.", "週末の営業時間は変わらず、土曜日は午前8時、日曜日は午前10時に開店いたします。"], ["Please note that our garden center will close early on holidays, so we recommend calling ahead if you plan to visit.", "ガーデンセンターは祝日には早く閉店いたしますので、ご来店の際は事前にお電話いただくことをお勧めします。"], ["Customers who would like to place an order for pickup can do so by pressing three at any time.", "店頭受け取りのご注文をご希望のお客様は、いつでも3を押していただければ承ります。"], ["Thank you again for shopping with us.", "ご利用いただき、あらためてありがとうございます。"]]}, {"id": "talk-01", "title": "新型掃除機のデモ", "cat": "talk", "type": "説明・トレーニング", "level": "TOEIC 600", "voice": "m", "s": [["Today I would like to show you our new vacuum cleaner, the CleanMax Two.", "本日は、当社の新しい掃除機、クリーンマックス・ツーをご紹介いたします。"], ["It is lighter than our old model, and it weighs only three pounds.", "旧モデルより軽く、重さはわずか3ポンドです。"], ["First, press the green button to turn it on.", "まず、緑のボタンを押して電源を入れます。"], ["Then, move the handle slowly across the floor.", "次に、ハンドルをゆっくり床の上で動かします。"], ["When the light turns red, the dust container is full.", "ライトが赤くなったら、ダストケースがいっぱいになった合図です。"], ["Simply push the release switch and empty it into the trash.", "解除スイッチを押して、ごみ箱に中身を捨てるだけです。"], ["Please try it yourself after this demonstration.", "このデモンストレーションの後で、ぜひご自身でお試しください。"]]}, {"id": "talk-02", "title": "新入社員への挨拶", "cat": "talk", "type": "説明・トレーニング", "level": "TOEIC 600", "voice": "f", "s": [["Welcome to Bridgeport Marketing, and thank you for joining our team.", "ブリッジポート・マーケティングへようこそ。私たちのチームに加わってくださりありがとうございます。"], ["Today is your first day, so we will keep things simple.", "今日は初日ですので、簡単に進めます。"], ["First, please collect your security badge from the front desk.", "まず、受付でセキュリティバッジを受け取ってください。"], ["After that, I will take you on a short tour of the building.", "その後、私が建物を簡単にご案内します。"], ["We will have lunch together at noon in the cafeteria.", "正午にカフェテリアで一緒に昼食をとります。"], ["This afternoon, you will meet your managers and set up your computers.", "午後は、上司の方々に会い、コンピューターの設定をします。"], ["If you have any questions, please feel free to ask me.", "ご質問があれば、遠慮なく私にお尋ねください。"]]}, {"id": "talk-03", "title": "工場の安全ルール説明", "cat": "talk", "type": "説明・トレーニング", "level": "TOEIC 600", "voice": "m", "s": [["Good morning, everyone, and thank you for coming to this safety briefing.", "皆さん、おはようございます。この安全説明会にお越しいただきありがとうございます。"], ["Before you enter the work area, you must put on a helmet and safety glasses.", "作業エリアに入る前に、ヘルメットと保護メガネを着用しなければなりません。"], ["Please keep all walkways clear, and do not leave boxes on the floor.", "通路はすべて空けておき、床に箱を置かないでください。"], ["If you see a spill, tell your supervisor right away.", "こぼれた液体を見つけたら、すぐに上司に伝えてください。"], ["In case of fire, leave the building through the nearest exit.", "火災の場合は、最も近い出口から建物の外に出てください。"], ["The meeting point is the parking lot behind the warehouse.", "集合場所は、倉庫の裏の駐車場です。"]]}, {"id": "talk-04", "title": "新しい経費精算の手順", "cat": "talk", "type": "説明・トレーニング", "level": "TOEIC 730", "voice": "f", "s": [["Starting next Monday, we will submit all expense reports through the new online system.", "来週の月曜日から、すべての経費報告書を新しいオンラインシステムで提出します。"], ["You no longer need to attach paper receipts to your forms.", "もう書類に紙の領収書を添付する必要はありません。"], ["Instead, take a photo of each receipt and upload it to your report.", "代わりに、各領収書を写真に撮って、報告書にアップロードしてください。"], ["Your manager will review the report within two business days.", "上司が2営業日以内に報告書を確認します。"], ["Once it is approved, the payment will appear in your next paycheck.", "承認されると、支払いは次回の給与に反映されます。"], ["If you have trouble logging in, contact the help desk before Friday.", "ログインで問題がある場合は、金曜日までにヘルプデスクに連絡してください。"]]}, {"id": "talk-05", "title": "新ソフトの社内研修", "cat": "talk", "type": "説明・トレーニング", "level": "TOEIC 730", "voice": "m", "s": [["Welcome to the training session for our new scheduling software, TimeTrack.", "新しいスケジュール管理ソフト、タイムトラックの研修へようこそ。"], ["This program will replace the shared calendar that we have used for years.", "このプログラムは、長年使ってきた共有カレンダーに代わるものです。"], ["To begin, open the Web browser and enter the address I have written on the board.", "まず、ウェブブラウザを開いて、私がボードに書いたアドレスを入力してください。"], ["Next, log in with your employee number and the temporary password in your email.", "次に、社員番号と、メールに記載された仮のパスワードでログインしてください。"], ["Once you are inside, click the plus button to create a new meeting.", "中に入ったら、プラスボタンをクリックして新しい会議を作成します。"], ["You can invite colleagues and reserve a conference room at the same time.", "同僚を招待し、同時に会議室を予約することもできます。"], ["We will practice these steps together in a moment.", "これらの手順を、このあと一緒に練習します。"]]}, {"id": "talk-06", "title": "クレーム電話の対応法", "cat": "talk", "type": "説明・トレーニング", "level": "TOEIC 730", "voice": "f", "s": [["Today I will explain how to handle a customer complaint over the phone.", "本日は、お客様からの苦情電話への対応方法を説明します。"], ["First, listen carefully without interrupting, even if the customer sounds upset.", "まず、お客様が怒っているように聞こえても、さえぎらずに注意深く聞いてください。"], ["Second, apologize sincerely for the problem and thank the customer for calling.", "次に、問題について心から謝罪し、お電話いただいたことに感謝します。"], ["Then, write down the details, including the order number and the date of purchase.", "それから、注文番号や購入日を含む詳細を書き留めます。"], ["Explain what you can do to solve the problem, and give a clear deadline.", "問題を解決するためにできることを説明し、明確な期限を伝えてください。"], ["Finally, follow up with the customer to make sure that he or she is satisfied.", "最後に、お客様に連絡をとり、ご満足いただけたかを確認します。"]]}, {"id": "talk-07", "title": "新型タブレットの紹介", "cat": "talk", "type": "説明・トレーニング", "level": "TOEIC 730", "voice": "m", "s": [["Thank you all for attending the launch of the Orion tablet.", "オリオン・タブレットの発表会にご出席いただき、ありがとうございます。"], ["Unlike previous models, this device has a battery that lasts for fifteen hours.", "従来のモデルと違い、この端末のバッテリーは15時間持続します。"], ["The screen is bright enough to read outdoors, even on a sunny afternoon.", "画面は十分に明るく、晴れた日の午後でも屋外で読めます。"], ["As you can see, it also connects to the printer in the office without any cables.", "ご覧のとおり、ケーブルなしでオフィスのプリンターにも接続できます。"], ["The Orion will be available in stores on April tenth, with a special discount for early buyers.", "オリオンは4月10日に店頭で発売され、早期購入のお客様には特別割引があります。"], ["Please come to the front, and you are welcome to try one.", "どうぞ前にお越しください。ご自由にお試しいただけます。"]]}, {"id": "talk-08", "title": "新しい在宅勤務制度", "cat": "talk", "type": "説明・トレーニング", "level": "TOEIC 860", "voice": "f", "s": [["I would like to explain the revised remote work policy, which takes effect on the first of next month.", "来月1日に施行される、改定された在宅勤務制度について説明したいと思います。"], ["Employees with six months of service will be eligible to work from home up to three days per week.", "勤続6か月の社員は、週に最大3日まで在宅勤務ができるようになります。"], ["However, team leaders must make sure at least half of their staff is present in the office on Tuesdays and Thursdays.", "ただし、チームリーダーは、火曜日と木曜日に少なくとも半数のスタッフがオフィスにいるようにしなければなりません。"], ["Anyone interested should submit a request through the human resources portal by Friday.", "希望する方は、金曜日までに人事ポータルから申請してください。"], ["The company will also provide a monthly allowance to help cover internet costs at home.", "会社は、自宅のインターネット費用を補助するための月額手当も支給します。"], ["I will hold an open question session on Monday morning for anyone who needs further clarification.", "さらに説明が必要な方のために、月曜日の午前中に自由質問の場を設けます。"]]}, {"id": "talk-09", "title": "ポッドキャスト仕事術", "cat": "talk", "type": "説明・トレーニング", "level": "TOEIC 860", "voice": "m", "s": [["Welcome back to Productive Minds, the show that helps busy professionals get more done in less time.", "忙しいビジネスパーソンが短い時間でより多くのことをこなせるよう手助けする番組、プロダクティブ・マインズへおかえりなさい。"], ["Our tip for today is about meetings, which many managers believe consume far too much of the working week.", "今日のヒントは会議についてです。多くの管理職が、会議は勤務時間の大半を費やしすぎると考えています。"], ["Before you schedule any meeting, ask yourself whether the same goal could be achieved with a brief email.", "会議を設定する前に、同じ目的が短いメールで達成できないか自問してください。"], ["If a meeting is truly necessary, send a written agenda at least a day in advance so that participants can prepare.", "会議が本当に必要な場合は、参加者が準備できるよう、少なくとも1日前に書面の議題を送りましょう。"], ["Finally, end every session by assigning each action item to one person with a clear deadline.", "最後に、各アクション項目を明確な期限とともに1人に割り当てて、毎回の会議を終えましょう。"], ["Try this approach for two weeks, and you will probably reclaim several hours.", "この方法を2週間試せば、おそらく数時間を取り戻せるでしょう。"]]}, {"id": "talk-10", "title": "品質検査の新手順説明", "cat": "talk", "type": "説明・トレーニング", "level": "TOEIC 860", "voice": "f", "s": [["Thank you for joining this briefing on the revised quality inspection procedure that begins next quarter.", "来四半期から始まる、改定された品質検査手順についての説明会にご参加いただき、ありがとうございます。"], ["Previously, each product was inspected only once, immediately before it was shipped to the customer.", "これまでは、各製品はお客様に出荷される直前に1度だけ検査されていました。"], ["Under the new system, items will be checked at three stages, which should help us identify defects much earlier.", "新しいシステムでは、製品は3つの段階で検査され、不具合をはるかに早く見つけられるようになります。"], ["Inspectors who find a problem must record it in the database and notify the production supervisor within one hour.", "問題を見つけた検査員は、データベースに記録し、1時間以内に生産責任者に報告しなければなりません。"], ["Although this will require additional effort at first, it will reduce returns and improve customer satisfaction over time.", "最初は追加の労力が必要ですが、時間とともに返品が減り、顧客満足度が向上するでしょう。"], ["Training sessions will begin on Wednesday, and attendance is mandatory for all inspection staff.", "研修は水曜日から始まり、すべての検査担当者の出席が必須です。"]]}];
